-- Insert biblical characters
INSERT INTO biblical_characters (id, name, name_en, era, role, kingdom, character_type, lesson, summary, witness, scripture_ref, prayer, is_active) VALUES
    (1, '亚当', 'Adam', '族长时代', '其他', NULL, '警戒', '顺服的重要性', '第一个人类，因不顺服神而堕落，将罪带入世界。', '亚当是全人类的镜子：一个选择改变了整个历史。神给了他完美的环境、清晰的命令，但他仍然选择了自己的意志而非神的旨意。他的悲剧不是犯了大罪，而是在小小的试探面前沉默、观望、然后跟随。', '创2-3', '主耶稣，你是第二亚当，你用顺服修复了亚当的悖逆。帮助我在今天面对的每一个选择中，选择你的旨意而非我自己的欲望。当我想推卸责任时，让我想起你的十字架。阿们。', true),
    (2, '夏娃', 'Eve', '族长时代', '女性', NULL, '警戒', '警惕试探的入口', '第一个女人，被蛇的诡辩动摇，走向悖逆，一个质疑改变了一切。', '夏娃的陷落从一个问题开始：神真的这样说吗？试探不是从行动开始，而是从怀疑神的话语开始。她看见果子好看好吃，就按感官和逻辑做决定，而非按神的话。我们每天也面对同样的模式。', '创2-3', '主，夏娃的故事就是我的故事。我也常常先看再想，凭感觉做决定。让你的话语成为我最终的权威，让我识别那些质疑你话语的声音，在它们开始时就拒绝它们。阿们。', true),
    (3, '该隐', 'Cain', '族长时代', '其他', NULL, '警戒', '嫉妒是杀手', '第一个杀人犯，因嫉妒弟弟亚伯被神悦纳而将他杀害，是嫉妒未处理的终极警告。', '该隐的悲剧从未处理的嫉妒开始。神已经警告他：罪伏在门口，你要制伏它。但他不听，最终成了杀人犯。嫉妒不处理会升级为仇恨，仇恨不处理会升级为行动。神在罪行之前给了他机会，他拒绝了。', '创4', '主，我心里也有嫉妒的种子。帮助我在嫉妒刚出现时就向你认罪，而不是让它在心里生根发芽。让我能真心为他人的祝福感恩，因为你对每个人的带领都是独特的。阿们。', true),
    (4, '亚伯', 'Abel', '族长时代', '其他', NULL, '正面', '献上最好的给神', '第一个殉道者，以信心献上头生的羊和脂油，蒙神悦纳，短暂的生命成为永恒的见证。', '亚伯的故事虽短，却力量巨大。他献上头生的羊和羊的脂油——最好的，而非方便剩余的。他的敬拜出于信心，神看见了他的心。他生命虽短，却在来11章进了信心名人堂，被称为还在说话的人。', '创4', '主，让我有亚伯的心。不凑合，不献剩余的，而是献上最好的。让我的敬拜出于真实的信心，而非宗教的习惯和他人的眼光。阿们。', true),
    (6, '挪亚', 'Noah', '族长时代', '其他', NULL, '正面', '逆境中的顺服', '在全地败坏的时代，因信心顺服神造方舟，全家得救，成为新人类的起点。', '挪亚的顺服在当时看来是荒唐的——没有大洪水的迹象，没有人支持，可能被嘲笑几十年。但他按神说的每一步去做，没有打折，没有修改计划。这是信心：在看不见的时候仍然行动，不需要别人理解。', '创6-9', '主，挪亚的信心是行动的信心。让我在你给我清晰指引时不再等待，而是立即顺服。在旁人不理解时给我挪亚的坚持，在成功后给我警醒。阿们。', true),
    (7, '亚伯拉罕', 'Abraham', '族长时代', '族长', NULL, '正面', '信心回应神的呼召', '信心之父，蒙神呼召离开本地，相信不可能的应许，被称为义，成为多国之父。', '亚伯拉罕是信心的终极范例。神叫他去，他不知道去哪里就出发了。神应许他有儿子，他在一百岁时仍然相信。神叫他献以撒，他举刀的手告诉我们他真的相信神能叫死人复活。信心不是感觉，是行动。', '创12-25', '主，亚伯拉罕的信心是我的目标。当你呼召我出去时，帮助我不等待地图就出发。当我面对以撒时，让我的信靠比我的爱更深。在我惧怕时，让我向你诚实而非转向谎言。阿们。', true),
    (8, '撒拉', 'Sarah', '族长时代', '女性', NULL, '混合', '信心的忍耐', '亚伯拉罕的妻子，一生等候神的应许，曾不信地笑，最终在九十岁生下以撒。', '撒拉等了几十年。她在帐棚里听见天使说一年后生儿子，她笑了——那是苦涩的笑。但神没有因她的不信而取消应许。她最终成为以撒的母亲，进入来11章信心名人堂，被称为以神为信实的。', '创12-23', '主，撒拉的等候里有笑声、有眼泪、有错误，也有最终的信心。我也在等候你的应许。帮助我在等候中不用自己的方法代替你的旨意，不让苦涩代替信心。阿们。', true),
    (9, '以撒', 'Isaac', '族长时代', '族长', NULL, '正面', '完全降服神', '应许之子，在摩利亚山顺服被献祭，预表基督的顺服，后来成为以色列的第二代族长。', '以撒最震撼的一刻是在摩利亚山上：他问父亲祭物在哪里，父亲说神会预备。他相信了。他顺服地被捆绑在坛上，没有反抗。这是从父亲的信心中学到的顺服——相信神会为我预备。', '创21-28', '主，以撒的顺服是最深刻的信心功课。帮助我在你的带领下不挣扎，相信你会预备我所需要的。在我不明白你的计划时，让我说：神必自己预备。阿们。', true),
    (10, '雅各', 'Jacob', '族长时代', '族长', NULL, '混合', '神改变欺骗者', '从欺骗哥哥的人到被神改名为以色列，是神花几十年时间改变最顽固性格的真实见证。', '雅各是圣经中最真实的人物之一——有心机、有欲望、也有对属灵祝福的渴望。神没有放弃他，而是花了几十年——通过婚姻、工作、逃跑、夜里摔跤——来改变他。雅博渡口的一夜，他抓住神不放，终于得着了新名字。', '创25-50', '主，雅各的故事让我看见你对顽固之人的耐心。我也有雅各式的算计和逃避。谢谢你没有放弃我。让我在雅博渡口经历你，被你改名、被你更新，成为你所命名的人。阿们。', true),
    (11, '约瑟', 'Joseph', '族长时代', '其他', NULL, '正面', '逆境饶恕与神的主权', '被卖为奴却高升为埃及宰相，饶恕兄弟，见证神在苦难中的主权。', '约瑟的一生充满了不公——被嫉妒、被出卖、被诬陷、被遗忘。但他在每一个低谷都持守了品格，最终神将他高升。最震撼的是他对兄弟的话：你们的意思是要害我，但神的意思是要保全人的性命。这是神主权的最深宣告。', '创37-50', '主，约瑟的话是我最需要的信念：你们的意思要害我，但神的意思是好的。帮助我在不公平的处境中相信你的主权，在有机会报复时选择饶恕。阿们。', true),
    (12, '摩西', 'Moses', '出埃及时代', '先知', NULL, '正面', '谦卑领导', '带领以色列出埃及的伟大先知，被称为地上最谦卑的人，是谦卑领导的最高典范。', '摩西的一生有两半：前四十年他以为自己是什么人，中间四十年神让他知道自己算什么，后四十年神通过他完成了人类最伟大的救赎故事之一。真正的领袖不是靠能力，而是靠与神同在的谦卑。', '出1-申34', '主，摩西是你用来领导的谦卑器皿。让我明白真正的领导力来自亲近你，而非来自我的能力和地位。在我想凭自己解决时，提醒我先去寻求你。阿们。', true),
    (13, '亚伦', 'Aaron', '出埃及时代', '祭司', NULL, '混合', '圣洁事奉的责任', '第一位大祭司，与摩西同工，但在压力下造了金牛犊，是妥协的警告。', '亚伦是神选立的大祭司，有极高的呼召。但当摩西上山久久不下来，百姓施压时，他妥协了，造了金牛犊。他的解释是：我把金子扔进火里，就出来这头牛——这是掩盖责任的最荒唐借口。', '出4-民20', '主，亚伦的妥协提醒我：越高的呼召需要越多的依靠你。帮助我在压力下不妥协，在有地位时更谦卑。当我失败时，让我诚实承认而非找借口。阿们。', true),
    (14, '米利暗', 'Miriam', '出埃及时代', '女性', NULL, '警戒', '领袖骄傲的代价', '女先知，带领妇女赞美，但因嫉妒和骄傲批评摩西而被击打长大麻风，是成功后骄傲的警告。', '米利暗是真实有恩赐的女先知，她在红海边带领妇女赞美神，是荣耀的时刻。但成功之后她开始用外在理由（摩西娶了古实女子）批评神的仆人，根本原因是嫉妒和骄傲。神立刻管教了她。', '出15，民12', '主，米利暗的故事是成功后最需要的警告。帮助我在成功时更加谦卑，在批评他人前先检查我的动机。让我的恩赐服事你，而非服务我的骄傲。阿们。', true),
    (17, '底波拉', 'Deborah', '士师时代', '女性', NULL, '正面', '勇敢领导', '女先知女士师，在男人退缩的时代挺身而出，带领以色列得胜，是勇敢回应神呼召的典范。', '底波拉生活在以色列最混乱的士师时代。神选了一个女人来领导——不是因为没有男人，而是因为她愿意回应呼召。当巴拉不敢单独出战时，她陪他上战场。勇气不是没有恐惧，而是尽管恐惧仍然行动。', '士4-5', '主，底波拉的故事让我看见：你呼召愿意顺服的人，无论他们的背景如何。当身边的人退缩时，给我底波拉的勇气说：我愿意。阿们。', true),
    (18, '基甸', 'Gideon', '士师时代', '其他', NULL, '混合', '以少胜多靠神能力', '神用三百人大败十三万五千米甸军，见证神的能力在人的软弱中彰显，但晚年铸造了金以弗得。', '基甸第一次出现在酒榕里躲避敌人，神叫他大能的勇士。他问了三次神的确认才敢出发。但神偏偏要把三万人减到三百人，原因只有一个：让以色列不能归功于自己。结果不出所料，三百人得胜。', '士6-8', '主，你叫基甸大能的勇士，但他躲在酒榕里。你也这样看我——不是看我现在的软弱，而是看你能做成的。帮助我在软弱中仍然愿意被你使用。阿们。', true),
    (19, '参孙', 'Samson', '士师时代', '其他', NULL, '警戒', '自律失败的代价', '从娘胎蒙召的拿细耳人，有超自然的力量，却因私欲骄傲最终失去一切，是属灵恩赐需要品格的警告。', '参孙有神奇妙的恩赐——力量无比。但他的生命是一系列自我放纵的记录：娶外邦妻、寻妓女、爱大利拉。他的力量从未用于神所呼召的救赎事工。最终他在最软弱的地方被攻击。恩赐不等于品格。', '士13-16', '主，参孙的故事是对我最真实的警告。我也有自己的大利拉——那个让我一再软弱的地方。帮助我识别它，建立防线，不让恩赐因为品格的失守而蒙羞。阿们。', true),
    (20, '路得', 'Ruth', '士师时代', '女性', NULL, '正面', '忠贞与救赎', '摩押外邦女子，忠随婆婆拿俄米，成为大卫曾祖母，进入弥赛亚的家谱，是忠贞的最高典范。', '路得有一百个理由可以离开：丈夫死了，婆婆命令她回去，她在以色列是外人。但她说：你往哪里去，我也往那里去。这是最美丽的委身宣言。她的忠贞不是因为有保障，而是因为选择了爱。', '路得记', '主，路得的宣言是我想对你说的：你往哪里去，我也往那里去。在没有保障时选择委身，在陌生处境中选择忠贞。谢谢你看见每一个忠心的行动。阿们。', true),
    (21, '波阿斯', 'Boaz', '士师时代', '其他', NULL, '正面', '品格与怜悯', '富有的家业救赎主，以品格、仁慈和忠心迎娶路得，是品格决定影响力的典范。', '波阿斯第一次见到路得，他对自己的仆人吩咐要额外留麦穗给她，不要羞辱她。他没有等路得开口请求，主动用自己的品格表达关怀。真正的品格是在没有人要求时也选择善待弱势。', '路得记', '主，波阿斯的品格是我想要有的：主动、善待弱势、忠心负责任。让我的品格在没有人要求时也选择善，在有能力时承担责任。阿们。', true),
    (22, '哈拿', 'Hannah', '士师时代', '女性', NULL, '正面', '祷告的能力', '因长期不孕而受苦，痛哭祷告神，神垂听，生了先知撒母耳，是真实祷告的最深典范。', '哈拿的祷告不是优美的词汇，而是心碎的眼泪。她在圣殿里大哭，以利误以为她喝醉了。但神看见了她心里的苦痛。真实的祷告不是表演给人看，而是将最深的痛苦带到神面前。', '撒上1-2', '主，哈拿的祷告是最真实的祷告。让我也学会将心碎带到你面前，不是优美地表演，而是真实地倾诉。谢谢你垂听心碎的祷告。阿们。', true),
    (24, '扫罗', 'Saul', '王国时代', '君王', '统一王国', '警戒', '骄傲不顺服的代价', '以色列第一位王，因骄傲和不顺服被神废弃，是顺服胜于祭祀最深刻的活教材。', '扫罗开始时谦卑——他躲在器具中间，说我算什么？但当他有了王权，他开始自作主张。他在吉甲擅自献祭，他在亚玛力战役保留了战利品，每次都有很好的理由。但神说：顺服胜于祭祀。', '撒上9-31', '主，扫罗的悲剧不是一次大罪，而是一系列小小的不顺服积累而成。帮助我不在小事上对你的旨意打折，不用献祭掩盖不顺服。顺服胜于祭祀，让这成为我的生命准则。阿们。', true),
    (25, '大卫', 'David', '王国时代', '君王', '统一王国', '混合', '悔改敬拜合神心意', '合神心意的王，犯了奸淫和杀人的重罪，却真实地悔改，成为旧约最伟大的敬拜者。', '大卫犯的罪不轻——奸淫、谎言、谋杀。但神说他是合我心意的人，原因不是他完美，而是他对神的心是真实的。诗篇51篇是人类最深刻的悔改祷告。神看重的不是没有失败，而是失败后真实的转回。', '撒上16-王上2', '主，大卫的诗篇是我最真实的祷告词典。神啊，求你为我造清洁的心，使我里面重新有正直的灵。在我跌倒之后，帮助我像大卫一样真实地回到你面前，不掩盖、不自辩。阿们。', true),
    (29, '所罗门', 'Solomon', '王国时代', '君王', '统一王国', '混合', '智慧的起点是敬畏神', '以色列最智慧的王，建造圣殿，写下箴言和传道书；前期以敬畏神为根基治国，晚年因外邦妻妾将心偏离神。', '神两次向他显现，他求的是听断是非的智慧，不是财富。箴9:10：敬畏耶和华是智慧的开端。智慧不是头脑的产物，而是敬畏神的结果。', '王上1-11', '主，所罗门在起点求智慧，你就赐给他一切。帮助我在每个开始先求你。在我拥有最多时，让我仍然心向你。阿们。', true),
    (30, '亚哈', 'Ahab', '王国时代', '君王', '北国以色列', '警戒', '受不良影响的危险', '北国最恶之王，受妻子耶洗别影响引入巴力崇拜，谋取拿伯的葡萄园；但在先知警告后自卑，得到神暂缓审判的令人震惊的回应。', '他做了比前列王更恶的事。但当以利亚传达神的审判时，他撕裂衣服穿麻衣禁食。神说：你看见亚哈在我面前自卑吗？即使部分的谦卑，神也注意到。', '王上16-22', '主，亚哈的部分谦卑神也看见了。帮助我不以亲近之人的偏离作为自己远离你的借口，在先知的话来到时真实回应你。阿们。', true),
    (31, '约沙法', 'Jehoshaphat', '王国时代', '君王', '南国犹大', '正面', '危机中寻求神', '犹大好王，三国联军压境时宣告禁食带领全民祷告，神亲自为他们争战；也曾与恶王亚哈结盟险些送命。', '他的祷告：神啊，我们不知道怎样办，我们的眼目单仰望你。不假装有方案，宣告倚靠。神的回应：这场仗不是你们的，乃是神的。', '代下17-20', '主，约沙法说：我们的眼目单仰望你。帮助我在最不知所措时也以同样诚实的姿态来到你面前。这场仗是你的，不是我的。阿们。', true),
    (32, '以利亚', 'Elijah', '王国时代', '先知', NULL, '正面', '属灵争战与休息', '以色列最火热的先知，在迦密山以一人对抗四百五十个巴力先知得胜；随后在罗腾树下崩溃，被神用饼和水恢复，后被火车接走。', '迦密山得胜后，他进入最深的低谷：主啊，够了，求你取我的命。神没有说教，让他睡觉，送来饼和水。属灵最高峰后往往是情绪最低谷——神知道，先照顾身体。', '王上17-王下2', '主，以利亚在高峰之后崩溃，你送来饼和水。帮助我在筋疲力尽时先接受你的照顾，不强撑。谢谢你在我最软弱时也不放弃我。阿们。', true),
    (34, '希西家', 'Hezekiah', '王国时代', '君王', '南国犹大', '正面', '祷告得拯救', '犹大历史上最敬虔的王之一，将西拿基立的恐吓信铺在神面前祷告得胜；又在病危中祷告得医治，是祷告神迹的真实案例。', '亚述大军压境，希西家进圣殿，将信铺在神面前：求你俯耳而听，睁眼而看。然后神在一夜之间灭了十八万五千亚述兵。真实问题带到神面前，神亲自出手。', '王下18-20', '主，希西家把恐吓信铺在你面前。帮助我把今天让我最焦虑的事也带到你面前，具体诚实地告诉你，然后等候你回应。阿们。', true),
    (36, '以赛亚', 'Isaiah', '王国时代', '先知', NULL, '正面', '圣洁异象与使命呼召', '旧约最伟大的先知之一，看见神的荣耀后说：我在这里，请差遣我；预言弥赛亚的受苦与荣耀，写下了最完整的救赎蓝图。', '以赛亚在圣殿看见神坐在高高宝座上，说：祸哉，我灭亡了！但神用红炭洁净他，然后说：谁肯为我们去呢？以赛亚说：我在这里，请差遣我。洁净之后是差遣。', '赛1-66', '主，以赛亚被你的圣洁震撼，然后被你差遣。帮助我也先在你圣洁面前认识自己，被洁净，然后说：我在这里，请差遣我。阿们。', true),
    (37, '耶利米', 'Jeremiah', '王国时代', '先知', NULL, '正面', '艰难中忠心', '哭泣的先知，经历逼迫、下监、被投泥坑，却从未停止传讲神的话；他诚实的哀歌成为圣经最深刻的人类痛苦表达。', '他说：我不再提耶和华，也不奉祂名讲论，我心里却有烧着的火，闭塞在我骨中，我就含忍不住。神的话在他里面是火——想停，却停不下来。', '耶1-52', '主，耶利米心里有烧着的火，含忍不住。帮助我也让你的话在我心里燃烧，在逼迫和无结果中仍然开口。不为结果，只为忠心。阿们。', true),
    (39, '但以理', 'Daniel', '王国时代', '先知', NULL, '正面', '职场持守不妥协', '被掳巴比伦的希伯来青年，在两代王朝持守信仰，因祷告被投狮子坑仍无恙，留下异象预言和清洁品格的双重见证。', '每天三次开窗向耶路撒冷祷告——他知道有禁令，仍然照常。这不是挑衅，而是他的生活方式本来就是如此，禁令无法改变他的习惯。信仰不是在被允许时才实践的，而是生命的常态。', '但1-12', '主，但以理每天三次祷告，即使面对狮子坑。帮助我把祷告建立成生活习惯，不只在危机中才呼求你。阿们。', true),
    (40, '何西阿', 'Hosea', '王国时代', '先知', NULL, '正面', '神永不放弃的爱', '被神呼召娶不贞的妻子歌蔑，用自己婚姻的痛苦活出神对悖逆以色列仍然不离不弃的爱；他的生命是一场活的比喻。', '歌蔑离开他，他仍然去奴隶市场把她买回来。神说：你再去爱那被人所爱却行淫的妇人，如同耶和华爱以色列人一样。神的爱不建立在对方的回应上，而是建立在神的性情上。', '何1-14', '主，何西阿的爱是你爱的镜子——主动、持续、不因对方的背离而停止。帮助我也以这样的爱去爱那些难以爱的人，因为你先这样爱了我。阿们。', true),
    (42, '以斯帖', 'Esther', '被掳归回时代', '女性', NULL, '正面', '为民冒险', '波斯宫廷里的犹太孤女，在哈曼计划灭绝犹太人时冒死进入王前求情，拯救了全族；她的位置是神的预备。', '末底改说：焉知你得了王后的位分不是为现今的机会吗？以斯帖的回应：我若死就死吧。她的位置不是巧合，是神的安排；她的行动不是冲动，是禁食祷告三天后的顺服。', '斯1-10', '主，以斯帖在最危险的时刻说：我若死就死吧。帮助我在关键时刻不因惧怕而沉默，相信你把我放在这里是有目的的。阿们。', true),
    (43, '末底改', 'Mordecai', '被掳归回时代', '其他', NULL, '正面', '不屈服于压力', '以斯帖的养父，拒绝向哈曼下拜，揭露了谋杀王的阴谋；他的不妥协成为整个民族得救的连锁反应的起点。', '人人都向哈曼跪拜，只有末底改不跪不拜。他的理由不是傲慢，而是对神的敬拜不容许他向任何人下跪。一个人的忠心改变了整个民族的命运。', '斯1-10', '主，末底改在众人妥协时不跪拜。帮助我在压力最大时仍然分辨哪些是我无论如何不能妥协的，然后坚守。阿们。', true),
    (44, '尼希米', 'Nehemiah', '被掳归回时代', '其他', NULL, '正面', '祷告与行动并行', '波斯宫廷酒政，听见耶路撒冷城墙荒废后哭泣祷告，然后以极强的组织力带领重建城墙，是信心与行动结合的领袖典范。', '他在王面前祈求，然后立刻有具体计划：需要多少时间、哪些材料、通过哪些关卡。真实的信仰祷告不排除周全的计划。他靠神施恩的手，也靠精心的准备。', '尼1-13', '主，尼希米为城墙哭泣，然后站起来建造。帮助我在为神的事哭泣之后，也有同样的行动力，把眼泪变成计划，把计划变成建造。阿们。', true),
    (46, '约伯', 'Job', '族长时代', '其他', NULL, '正面', '苦难中的信靠', '极义的人，在毫无缘由的苦难中失去一切，经历了神的沉默，最终神在旋风中说话——不是答案，而是更真实的相遇。', '约伯最终的胜利不是答案，而是神的同在。神在旋风中说：你在哪里呢？约伯说：我从前风闻有你，现在亲眼看见你。苦难没有解释，却带来了更真实的相遇。', '约伯记', '主，约伯在苦难中没有得到全部答案，但他得到了你。帮助我在最痛的地方不逃离你，而是更深地进入你的同在。阿们。', true),
    (48, '马利亚', 'Mary', '新约时代', '女性', NULL, '正面', '完全顺服神的旨意', '耶稣的母亲，天使宣告她将怀圣灵感孕的子时，说：我是主的使女，愿照你的话成就。在完全未知中的顺服是极致的信心行动。', '天使的宣告包含了所有风险。她却说：我是主的使女，愿照你的话成就。她将婺稣的话藏在心里默想。顺服不是安静的，而是完全点头告诉不可被理解的奇妙。', '路1-2', '主，马利亚在不知道结果时说是。帮助我在你的呼召面前不等待明白再顺服，先说：愿照你的话成就。阿们。', true),
    (49, '彼得', 'Peter', '新约时代', '使徒', NULL, '混合', '从否认到复兴', '从渔夫到磐石，经历否认主，被恢复后成为初代教会柱石。', '彼得的生命包含效法与警戒两面。神的恢复能超越我们最大的失败。', '太4，约13-21，徒2', '主，在我否认你之后，你仍然问我你爱我吗。谢谢你的恢复。', true),
    (50, '约翰', 'John', '新约时代', '使徒', NULL, '正面', '在主里安息爱的使徒', '曾经是要叫火从天降的雷子，成熟后成为爱的使徒，晚年只传一句话：小子们，要彼此相爱。', '约翰在最后的晚餐俯在耶稣胸前——他的身份是主所爱的门徒。真正的成熟不是变得更有理论，而是变得更有爱。他年老时重复同一句话，因为这是主的吩咐，这就够了。', '约1-21，约一', '主，约翰从雷子变成爱的使徒。帮助我也在与你的亲密中得到改变，越成熟越有爱，而不是越老越冷漠。阿们。', true),
    (51, '保罗', 'Paul', '新约时代', '使徒', NULL, '正面', '恩典彻底改变生命', '从最凶残的教会逼迫者到最伟大的使徒，在大马士革路上被耶稣光打倒，进入了几十年巨大激进布道、创作、建立教会的以恩典为主题的人生。', '保罗说：我是罪人中的第一。神的恩典没有删去他的过去，而是将他的过去变成神恩典最大的见证。我靠着那加给我力量的，凡事都能做。', '徒9-28', '主，保罗说我是罪人中的第一，你却用他写下了新约最深刻的书信。帮助我相信我的过去不限制你的计划，你的恩典在我软弱中得以完全。阿们。', true),
    (57, '吕底亚', 'Lydia', '新约时代', '女性', NULL, '正面', '慷慨接待欧洲教会起点', '腓立比经营紫色布的成功商人，神开了她的心，她及全家受洗，随即强请保罗一行住进她家，成为欧洲第一间教会的摇篮。', '神开了她的心，使她留意保罗所讲的话。然后她立刻行动：和全家受洗，强请使徒住进她家。属灵的开放和家门的开放是同步的——心开了，家也开了。', '徒16', '主，吕底亚的心被你开启，她的家也随之开启。求你也开我的心，使我留意你在说的话，然后将我所有的也向你的国度开放。阿们。', true),
    (58, '亚居拉与百基拉', 'Aquila & Priscilla', '新约时代', '其他', NULL, '正面', '夫妻同工家庭服事', '帐篷制作夫妻，与保罗同住同工，开放家作教会，曾为保罗甘愿冒险；他们将亚波罗私下带到一旁更详细讲解神的道，是夫妻同工最美的典范。', '保罗说：他们为我的命将自己的颈项置之度外，不但我感谢他们，就是外邦的众教会也感谢他们。两个人的婚姻成为整个使徒时代福音运动的支柱之一。', '徒18，罗16', '主，亚居拉与百基拉用婚姻服事你的国。帮助我与最亲近的人一同朝向你的呼召，让我们的家成为你建造的地方。阿们。', true),
    (60, '多加', 'Tabitha', '新约时代', '女性', NULL, '正面', '爱心服事行善的生命', '约帕的女门徒，这人广行善事，多施周济；她死后，众寡妇拿着她所做的里衣外衣哭泣，她的服事留下了有名有姓有物件的痕迹。', '寡妇们拿着多加所缝的衣服哭泣——这不是抽象的服事，而是实实在在的针线和时间。她的生命因具体的爱而被人铭记。', '徒9', '主，多加用针线和时间服事了寡妇。帮助我也将信仰化为具体的行动，留下实实在在的爱的痕迹。阿们。', true),
    (61, '腓比', 'Phoebe', '新约时代', '女性', NULL, '正面', '忠心服事执事职分', '坚革哩教会女执事，保罗称她为众人的帮助者，也是保罗自己的帮助者，并托她将罗马书送达罗马教会——她是神学巨著的最初传递人。', '保罗在罗马书末尾郑重推荐腓比：我把我们的姊妹腓比介绍给你们。她在没有荣誉或头衔的时代忠心服事，用实际行动成为帮助保罗的人，并承担了传递罗马书这历史性的使命。', '罗16', '主，腓比在幕后忠心服事，承担了传递神话语的历史性使命。帮助我在任何岗位上都忠心，相信你看见每一个默默的服事。阿们。', true),
    (63, '哥尼流', 'Cornelius', '新约时代', '其他', NULL, '正面', '神接纳一切寻求祂的人', '罗马百夫长，敬畏神，多多周济百姓，常常祷告；他的祷告被神记念，神差遣彼得向他和他全家传福音，成为外邦人蒙圣灵的历史性时刻。', '天使对哥尼流说：你的祷告和你的周济已蒙神记念了。他在没有完整福音知识的情况下，以敬畏和慷慨寻求神，神记念了他。神寻找的是真心寻求祂的人。', '徒10', '主，哥尼流的祷告和周济被你记念。帮助我也以敬畏和慷慨的生活方式寻求你，相信你看见每一个真心寻求你的心。阿们。', true),
    (64, '尼哥底母', 'Nicodemus', '新约时代', '其他', NULL, '混合', '从夜间到公开的信心之路', '法利赛人，夜间来见耶稣，最后公开帮助安葬耶稣。', '尼哥底母的生命包含效法与警戒两面。信仰需要从私下走向公开。', '约3,7,19', '主，让我的信仰每一步都更公开、更勇敢地认同你。', true),
    (65, '马可', 'Mark', '新约时代', '其他', NULL, '混合', '失败后的恢复', '第一次宣教半途而废，后来被恢复，写下马可福音。', '马可的生命包含效法与警戒两面。失败不是终结，是新的起点。', '徒12-15，提后4', '主，让我相信我的失败不是你对我的最后定论。', true),
    (71, '塞特', 'Seth', '族长时代', '其他', NULL, '正面', '延续敬虔后裔', '神赐给亚当夏娃代替被杀之亚伯的儿子；在该隐的杀戮和黑暗之后，塞特的后裔开始呼求耶和华的名，是人类敬虔传承的延续者。', '创世记记载：那时人才开始呼求耶和华的名。这简短一句，在一个杀戮和混乱的时代，是塞特一系留下的灵性转折点。忠心延续信仰，即使世界正在堕落。', '创4-5', '主，塞特的后裔在黑暗时代开始呼求你的名。帮助我在我的家庭和影响圈中成为信仰传承的人，让下一代也认识你。阿们。', true),
    (72, '玛土撒拉', 'Methuselah', '族长时代', '其他', NULL, '正面', '生命在神手中', '人类历史上最长寿的人，活了969年；他是以诺的儿子，洪水之年正是他离世之年，神在他的生命之期间仍然等待、忍耐。', '玛土撒拉的寿数本身是神忍耐与恩典的信号——他去世的那年，洪水临到。神的时间表与人的生命相交织，没有任何日子是偶然的。', '创5', '主，玛土撒拉的一生告诉我你在忍耐等待。帮助我不因年日漫长而懈怠，在你给我的每一天里忠心度过。阿们。', true),
    (73, '以扫', 'Esau', '族长时代', '其他', NULL, '警戒', '轻看属灵福分', '为一碗红豆汤卖掉长子名分。', '以扫的故事是轻看属灵福分的真实警告。短视的满足比长远的属灵价值更危险。', '创25-36', '主，让我不因眼前的欲望轻看你赐给我的属灵福分。', true),
    (74, '利百加', 'Rebekah', '族长时代', '女性', NULL, '混合', '神引导婚姻但不可用诡计代替信心', '以撒的妻子，神奇妙引导她嫁给以撒，但后来偏爱雅各操控结局。', '利百加的生命包含效法与警戒两面。神可以引导婚姻，但不可用诡计替代信心。', '创24-27', '主，让我信靠你的引导，而非用人的诡计帮你实现旨意。', true),
    (75, '约基别', 'Jochebed', '出埃及时代', '女性', NULL, '正面', '勇敢保护生命', '摩西的母亲，在法老命令杀害所有希伯来男婴的威胁下，将婴儿摩西藏了三个月，然后编织芦苇篮放入尼罗河，以信心将儿子交在神手中；她后来被雇去哺育自己的孩子。', '她将孩子放在芦苇篮中——这不是绝望的放弃，而是信心的托付。神奇妙地让法老女儿将摩西捡起，又让约基别被雇为奶娘哺育自己的儿子。她的信心行动成为神拯救以色列历史的起点。', '出2', '主，约基别将最珍贵的儿子放入河中托付给你。帮助我也学会在极难之处将最重要的交在你手中，相信你的保护比我的把握更可靠。阿们。', true),
    (76, '西坡拉', 'Zipporah', '出埃及时代', '女性', NULL, '混合', '在文化差异中成为神的管道', '摩西的妻子，在关键时刻行割礼救了摩西的命。', '西坡拉的生命包含效法与警戒两面。在文化差异中仍能成为神计划的管道。', '出2,4', '主，让我在不同的背景中仍能顺服你的旨意。', true),
    (78, '喇合（进入迦南）', 'Rahab', '出埃及时代', '女性', NULL, '正面', '恩典超越过去的身份', '耶利哥城的妓女，听见耶和华为以色列所行的一切大事后心中生出信心，藏了探子，以朱红线为记，全家得救；她后来进入以色列成为大卫和弥赛亚的祖先之一。', '喇合说：我知道耶和华已将这地赐给你们。她是城中的外邦人，却比以色列人更早相信神的应许。她的信心建立在神作为的见证上，而不是在自己的背景或身份上。', '书2,6', '主，喇合以妓女的身份却进入了信心名人堂。帮助我不用自己的过去限制你的恩典，相信你能使用任何真心寻求你的人。阿们。', true),
    (79, '俄陀聂', 'Othniel', '士师时代', '其他', NULL, '正面', '第一位士师靠圣灵得胜', '以色列士师时代的第一位拯救者，迦勒的侄子；耶和华的灵降在他身上，他出征攻打古珊利萨田并胜利，使以色列地太平四十年。', '士师记描述他：耶和华的灵降在他身上，他作以色列的士师。神的灵是他得胜的来源，不是他自己的才干。这是士师时代的第一个模式，也是整个士师记的核心功课。', '士3', '主，俄陀聂在圣灵的力量下得胜。帮助我在面对属灵争战时先等候你的灵，然后在你的力量中勇敢行动，而不是靠自己硬撑。阿们。', true),
    (80, '耶弗他', 'Jephthah', '士师时代', '其他', NULL, '警戒', '草率许愿的代价', '士师，因草率的许愿而付出沉重代价。', '耶弗他的故事是草率许愿的代价的真实警告。向神许愿要慎重，情绪激动时不要轻率许愿。', '士11-12', '主，让我的话语少而精，在许愿之前先祷告思考。', true),
    (81, '巴拉', 'Barak', '士师时代', '其他', NULL, '混合', '软弱信心也被神使用', '与底波拉同工的将领，因信心不够要底波拉同行。', '巴拉的生命包含效法与警戒两面。不完全的信心比不信心更好，神也使用软弱的信心。', '士4', '主，即使我的信心软弱，让我仍然愿意踏出去，你会成全余下的。', true),
    (82, '罗波安', 'Rehoboam', '王国时代', '君王', '南国犹大', '警戒', '拒绝智慧建议致王国分裂', '所罗门之子，拒绝老人的建议，致使王国分裂。', '罗波安的故事是拒绝智慧建议致王国分裂的真实警告。骄傲地拒绝智慧建议会带来毁灭性的后果。', '王上12', '主，让我有谦卑的心，愿意听取智慧的建议。', true),
    (94, '古列', 'Cyrus', '被掳归回时代', '君王', '外邦君王', '正面', '神使用外邦君王成就计划', '波斯帝国开国君主，征服巴比伦后颁布圣旨准许犹太人返回故土重建圣殿——比以赛亚先知预言他的名字整整早了约150年，是旧约中最惊人的预言应验之一。', '耶和华对古列说：他是我的牧人，必成就我所喜悦的。神在古列还未出生时就称呼他的名字，指明他是神计划的执行者。神的主权跨越国界、宗教和时间。', '拉1', '主，你在150年前就预备了古列完成你的计划。帮助我相信你在我出生之前就已有你的计划，并帮助我配合你在这个时代的工作。阿们。', true),
    (95, '所罗巴伯', 'Zerubbabel', '被掳归回时代', '其他', NULL, '正面', '从废墟重建是信心的表达', '大卫后裔，带领第一批被掳者归回耶路撒冷，在敌人阻挠和百姓疲惫中坚持重建圣殿；先知撒迦利亚宣告：不是倚靠势力，不是倚靠才能，乃是倚靠我的灵，才能成事。', '神对他说：谁藐视这小事的日子呢？先知哈该则宣告：要刚强！要刚强！要动工！他在最艰难的环境中坚持到底，圣殿终于完工。从废墟重建是信心最具体的行动。', '拉2-6', '主，所罗巴伯在废墟中动工，在阻力中坚持。帮助我在生命的废墟面前不失去盼望，倚靠你的灵而非自己的能力，踏出重建的第一步。阿们。', true),
    (96, '耶何耶大', 'Jehoiada', '王国时代', '祭司', NULL, '正面', '属灵导师影响国家方向', '大祭司，在亚她利雅篡位危机中秘密保护幼年约阿施七年，然后精心策划政变使合法王位回归，带来以色列宗教复兴；他活了130岁，死后被葬于王陵。', '历代志记载：约阿施在世的时候，因为耶何耶大教训他，就行耶和华眼中看为正的事。一个属灵导师七年的隐秘保护和一生的引导，可以影响一个国家的走向。', '代下23-24', '主，耶何耶大七年的隐秘保护改变了一个国家的历史。帮助我也以忠心和耐心扶持身边神所托付给我的人，成为他们属灵路上的引导者。阿们。', true),
    (97, '非尼哈', 'Phinehas', '出埃及时代', '祭司', NULL, '正面', '为神圣洁热心', '亚伦之孙，在以色列人大肆与摩押女子行淫乱、拜巴力之时，挺身而出阻止一起公然的违逆，神因此停止瘟疫，并赐给他和平之约，永远的祭司职分。', '神说：非尼哈的热心是为我的缘故，他在以色列人中代我伸了怒气，我就没有在自己的忌恨中把他们灭绝。一个人的热心可以为整个群体代替神承受愤怒。', '民25', '主，非尼哈的热心是因爱你的圣洁。帮助我也对你所珍视的圣洁有真实的热心，在需要站立的时候有勇气站立，而不是随波逐流。阿们。', true),
    (99, '约瑟（耶稣父亲）', 'Joseph Father of Jesus', '新约时代', '其他', NULL, '正面', '默默顺服保护神的计划', '耶稣的养父，木匠，在极难处境下三次梦见天使并立刻顺服：接纳马利亚为妻、带家人逃往埃及、归回拿撒勒——每次都是即听即行，没有任何犹豫和申辩的记录。', '圣经从未记录约瑟说过一句话，但他的每一个行动都是立刻的顺服：他醒了就遵命行。他的沉默不是软弱，而是一种深刻的谦卑与信任——在神的计划中，他甘愿作看不见的保护者。', '太1-2', '主，约瑟的生命是默默顺服的典范。帮助我在你的呼召面前也能立刻行动，不等待人的认可，甘心在幕后忠心守护你所托付给我的。阿们。', true),
    (100, '撒迦利亚（约翰父亲）', 'Zechariah Father of John', '新约时代', '祭司', NULL, '混合', '从不信到歌颂神的恢复', '施洗约翰的父亲，因不信而哑，儿子出生后口开赞美神。', '撒迦利亚（约翰父亲）的生命包含效法与警戒两面。神对不信仍有怜悯，并给我们机会转变。', '路1', '主，在我不信的时刻，求你有耐心等候我转变。', true),
    (101, '马大', 'Martha', '新约时代', '女性', NULL, '警戒', '忙碌服事忘记最重要的事', '忙碌服事的姐妹，被耶稣提醒选择最好的。', '马大的故事是忙碌服事忘记最重要的事的真实警告。服事神不能替代亲近神。', '路10，约11', '主，让我不用忙碌的服事掩盖我不愿安静在你面前的心。', true),
    (102, '马利亚（伯大尼）', 'Mary of Bethany', '新约时代', '女性', NULL, '正面', '亲近神是一切服事的根基', '伯大尼的马利亚，在众人忙碌时选择坐在耶稣脚前听道，被称赞选择了那不能夺去的上好福分；她后来又用极贵的香膏抹耶稣的脚，被耶稣说：她所作的将来传扬的无论哪里，也要述说她所行的以为纪念。', '耶稣对忙碌服事的马大说：马利亚已经选择那上好的福分，是不能夺去的。在所有人都在服事时，她选择停下来亲近耶稣。这不是懒惰，而是对最重要事物的准确判断。', '路10，约12', '主，马利亚选择了那上好的福分。帮助我在忙碌中有勇气停下来，优先坐在你脚前，让亲近你成为我一切服事的源头。阿们。', true),
    (103, '拉撒路', 'Lazarus', '新约时代', '其他', NULL, '正面', '被复活成为神荣耀的舞台', '伯大尼人，耶稣的挚友，病死后被葬四天；耶稣在众人面前呼唤他从坟墓出来，他复活——此事直接触发了宗教领袖定意杀害耶稣的决定，他的死与复活成为基督受难的导火线。', '耶稣说：这病不至于死，乃是为神的荣耀，叫神的儿子因此得荣耀。拉撒路经历了死亡，却成了神最直接的荣耀舞台。神有时允许我们经历极深的幽谷，正是为了更大的荣耀。', '约11', '主，拉撒路的死成了你荣耀最直接的舞台。帮助我不因苦难绝望，而是相信你在我最深的困境中仍然在工作，要彰显你的荣耀。阿们。', true),
    (104, '犹大', 'Judas', '新约时代', '使徒', NULL, '警戒', '靠近神而心未改变的危险', '十二使徒之一，为三十块银子出卖耶稣。', '犹大的故事是靠近神而心未改变的危险的真实警告。长期靠近神而心未改变的危险。', '太26-27', '主，让我不只是外表跟随你，求你改变我内心的贪婪。', true),
    (105, '亚拿尼亚与撒非喇', 'Ananias and Sapphira', '新约时代', '其他', NULL, '警戒', '欺哄圣灵的代价', '卖地后谎报价钱，欺哄圣灵而死。', '亚拿尼亚与撒非喇的故事是欺哄圣灵的代价的真实警告。神看透内心，欺骗不能在圣灵面前隐藏。', '徒5', '主，让我在神面前绝对诚实，不因想得人称赞而造假。', true),
    (106, '西门（行邪术）', 'Simon Magus', '新约时代', '其他', NULL, '警戒', '恩赐不能购买', '撒马利亚行邪术者，信主后试图用钱购买圣灵能力。', '西门（行邪术）的故事是恩赐不能购买的真实警告。属灵恩赐不能用金钱或权力换取。', '徒8', '主，让我不将你的恩典商品化。', true),
    (107, '路加', 'Luke', '新约时代', '其他', NULL, '正面', '专业才华忠心服事', '外邦人医生，新约最多产的作者，写了路加福音和使徒行传；他以医生的精准观察力访谈目击者，细致记录耶稣的生平和初代教会历史，是唯一在保罗最后被囚时仍然陪伴他的同工。', '保罗在临终书信中写道：只有路加在我这里。当其他人因恐惧或利益而离去时，医生路加仍然在保罗身旁。他用自己的专业才华忠心记录，用自己的陪伴忠心服事。', '路，徒', '主，路加用医生的眼睛观察，用忠心的笔记录，用陪伴的心服事。帮助我也将我的专业才华完全献给你，成为你计划中忠心的管道。阿们。', true),
    (108, '西拉', 'Silas', '新约时代', '其他', NULL, '正面', '监狱中的赞美', '保罗的宣教伙伴，曾被鞭打、收押脚镣关在腓立比监狱的内牢；在午夜与保罗一同祷告唱诗，众囚犯都听见，地震发生，监门全开，狱卒因此归信基督，全家受洗。', '使徒行传记载：约到半夜，保罗和西拉祷告唱诗赞美神，众囚犯也侧耳而听。他们的赞美不是表演，而是在极痛和极暗中真实的信心流露，这赞美成了释放的力量。', '徒15-18', '主，西拉在脚镣和黑暗中选择赞美。帮助我在今天的痛苦和不公正中也选择赞美，相信你在黑暗中仍然工作，赞美是打开锁链的钥匙。阿们。', true),
    (109, '提多', 'Titus', '新约时代', '其他', NULL, '正面', '可托付重任的同工', '外邦人信徒，保罗的真儿子，被派往混乱的克里特教会整顿秩序、设立长老；保罗形容他为热心服事神百姓的人，是保罗最信任的使者之一，曾被派去处理哥林多教会的棘手危机。', '保罗写道：我留你在克里特，是要你将那所缺少的事都整理妥当。提多是被委以最困难任务的人——克里特岛的人以不诚实著称，他却要在那里建立诚实的教会。', '多1-3', '主，提多被差遣到最难的地方，却忠心完成任务。帮助我也愿意去最需要的地方，成为一个品格扎实、可以被托付重任的同工。阿们。', true),
    (112, '底马', 'Demas', '新约时代', '其他', NULL, '警戒', '爱世界最终离弃服事', '保罗的同工，最终因贪爱世界离弃了保罗和事奉。', '底马的故事是爱世界最终离弃服事的真实警告。长期的事奉不等于最终的忠心。', '提后4', '主，保护我不因世界的吸引而在最后阶段放弃你。', true),
    (113, '拿但业', 'Nathanael', '新约时代', '使徒', NULL, '正面', '没有诡诈是信仰的根基', '加利利人，在腓力邀请他来见耶稣时直率地问：拿撒勒还能出什么好的吗？耶稣一见他便说：看哪，这是个真正的以色列人，他心里是没有诡诈的；拿但业问你怎么认识我，耶稣说在腓力叫你以先我看见你了，他立刻认信：你是神的儿子！', '耶稣对他说：你心里是没有诡诈的。这是耶稣对门徒最高的品格评语之一。拿但业的直率有时像怀疑，但他的内心没有算计，没有虚伪，这正是耶稣最珍视的品格。', '约1', '主，拿但业的内心没有诡诈，你称赞了他。帮助我也活出没有虚伪的信仰——对你诚实，对人真实，愿意在疑惑中仍然来到你面前。阿们。', true),
    (114, '亚拿尼亚（大马士革）', 'Ananias of Damascus', '新约时代', '其他', NULL, '正面', '克服恐惧接纳刚悔改的人', '大马士革门徒，神在异象中呼叫他去找扫罗（保罗）；他诚实地表达了自己的恐惧——扫罗正是来迫害基督徒的——但在神重申命令后立刻顺服，去到扫罗那里，称他为兄弟，为他施洗。', '亚拿尼亚对神说：主啊，我听见许多人说，这人怎样在耶路撒冷多多苦害你的圣徒。他的恐惧是真实的，但他没有用恐惧阻止顺服。他是第一个称呼保罗为「兄弟」的基督徒。', '徒9', '主，亚拿尼亚害怕，但还是去了。帮助我在恐惧中仍然顺服你的呼召，愿意成为第一个向悔改的人伸出手的人。阿们。', true),
    (115, '彼拉多', 'Pilate', '新约时代', '其他', NULL, '警戒', '明知无罪却妥协政治', '明知耶稣无罪，却因政治压力判祂死。', '彼拉多的故事是明知无罪却妥协政治的真实警告。对真理的妥协不因政治必要而被神接纳。', '太27', '主，让我在真理面前有勇气，不因政治或社会压力而妥协。', true),
    (116, '该亚法', 'Caiaphas', '新约时代', '祭司', NULL, '警戒', '宗教外衣掩盖黑暗动机', '大祭司，用宗教理由处死耶稣，却无意中说出了预言。', '该亚法的故事是宗教外衣掩盖黑暗动机的真实警告。宗教外衣可以掩盖最黑暗的动机。', '约18', '主，让我有诚实的内心，不用宗教掩盖我的私欲。', true),
    (117, '希律', 'Herod the Great', '新约时代', '君王', '外邦君王', '警戒', '权力无法阻挡神的旨意', '杀死伯利恒婴孩，却无法阻止神的计划。', '希律的故事是权力无法阻挡神的旨意的真实警告。再大的权力也无法阻挡神的旨意。', '太2', '主，让我明白任何人的权力在你的旨意面前都是有限的。', true),
    (118, '西庇太的儿子们', 'Sons of Zebedee', '新约时代', '使徒', NULL, '混合', '从求高位到甘愿服事', '雅各和约翰求坐高位，后来成为忠心的殉道者和爱的使徒。', '西庇太的儿子们的生命包含效法与警戒两面。属灵成长是从求荣耀到甘心服事的旅程。', '太20，可10', '主，让我的属灵成长也是这样的转变——从求荣耀到甘心服事。', true),
    (120, '约翰（启示录）', 'John of Patmos', '新约时代', '使徒', NULL, '正面', '患难放逐中领受最大启示', '使徒约翰晚年因信仰被流放至拔摩孤岛；在那孤立、与世隔绝的处境中，他在主日被圣灵感动，见到复活升天的基督，领受了整个新约中篇幅最长、视野最宏大的启示——将来全史的异象——并将其传给受迫害的七个教会。', '约翰在启示录开篇写道：我约翰，就是你们的弟兄，和你们在耶稣的患难、国度、忍耐里同有分。他不以领袖自居，而是以同受苦难的弟兄身份说话。最深刻的启示来自最深的孤独。', '启1-22', '主，约翰在流放的孤岛上领受了最大的启示。帮助我在今天最孤立、最困难的处境中仍然等候你，相信你在黑暗中仍然有话要对我说。阿们。', true),
    (121, '亚撒', 'Asa', '王国时代', '君王', '南国犹大', '混合', '初期改革后期依靠人', '犹大好王，初期除去偶像、依靠神得胜，晚年却依靠外邦王大亚蒙，不再信靠神。', '亚撒的一生是双阶段的对比：前期的改革热情与后期的依靠人形成鲜明对比。他的故事警告我们：属灵热情需要终身维持，而不只是开始。', '代下14-16', '主，亚撒的晚年提醒我：信仰不能靠老本。帮助我每天更新对你的依靠，不让成功或年岁使我离开你。阿们。', true),
    (123, '约坦', 'Jotham', '王国时代', '君王', '南国犹大', '正面', '安静忠心的正直领导', '犹大王，行正直，日渐强盛，是安静忠心领导的典范。', '约坦没有戏剧性的危机或失败，只是稳定地行在神面前，日渐强盛。忠心有时不是戏剧性的，而是安静、持续的。', '代下27', '主，约坦的生命告诉我：忠心不一定需要大事件。帮助我在平凡日子里安静地行在你面前，日渐强盛。阿们。', true),
    (124, '亚哈斯', 'Ahaz', '王国时代', '君王', '南国犹大', '警戒', '不信靠神而求人的后果', '犹大恶王，不信靠神，拜偶像向亚述求援，将国家带入属灵和政治的混乱。', '以赛亚给他求兆头的机会，他说：我不求。表面虔敬，实际是拒绝神。更信任亚述军队胜过神的应许。', '代下28', '主，亚哈斯拒绝你的帮助。帮助我在最大的压力下转向你而非转向人。阿们。', true),
    (125, '玛拿西', 'Manasseh', '王国时代', '君王', '南国犹大', '混合', '极深的罪与极大的悔改', '犹大历史上最恶的王，但在极刑下真心悔改，神恢复了他，是悔改永不嫌迟的见证。', '他做了最恶的事，被俘到巴比伦在极刑中极其谦卑地呼求神。神垂听了。这是圣经最惊人的悔改故事之一。', '代下33', '主，玛拿西的悔改告诉我：不管我走了多远，你的手仍然可以够到我。谢谢你不放弃最深的罪人。阿们。', true),
    (126, '耶罗波安二世', 'Jeroboam II', '王国时代', '君王', '北国以色列', '警戒', '物质兴盛掩盖属灵堕落', '北国统治时间最长的王，政治经济兴盛，却在属灵上极其败坏，是外强中干的典型。', '他的时代是北国最富裕的，但阿摩司呼吁：你们的歌声是噪音，财富建立在不公义上。兴盛不等于蒙福。', '王下14', '主，耶罗波安的时代警告我：繁荣可以是最美丽的谎言。帮助我不被外在成功迷惑。阿们。', true),
    (127, '何细亚', 'Hoshea', '王国时代', '君王', '北国以色列', '警戒', '国家灭亡前的失败领导', '北国最后一位王，在亚述面前首鼠两端，没有依靠神，最终北国被亚述灭亡。', '面对亚述压力，一方面朝贡，一方面暗中联络埃及。这种靠外交手腕的双面策略最终导致了北国的覆灭。', '王下17', '主，何细亚的失败提醒我：在最大的危机中不能靠左右逢源，只能依靠你。阿们。', true),
    (128, '亚他利雅', 'Athaliah', '王国时代', '女性', NULL, '警戒', '野心与权力欲的极端危险', '犹大唯一一位女王，杀死王室后裔篡位，是权力野心不受神约束时最极端的结果。', '她的野心让她杀死自己的孙子们来保住权位。这是把权力放在神之上时的最极端案例。', '王下11', '主，亚他利雅的故事是最深刻的权力警告。帮助我在任何位置上都把权力当作服侍的工具。阿们。', true),
    (130, '亚玛谢', 'Amaziah', '王国时代', '君王', '南国犹大', '混合', '半途而废与骄傲的危险', '犹大王，初期行神所喜悦的事，但拜了以东的神像，又在胜利后骄傲挑衅以色列王导致失败。', '打胜了以东，竟然带回以东的神像来拜。神说：他们不能救自己，怎能救你？骄傲使人盲目。', '代下25', '主，亚玛谢在胜利后骄傲，在警告面前固执。帮助我在成功后更加谦卑。阿们。', true),
    (131, '约珥', 'Joel', '王国时代', '先知', NULL, '正面', '悔改带来圣灵的复兴', '先知，呼召以色列在蝗灾国难中悔改，预言五旬节圣灵浇灌，是悔改与复兴盼望的先知。', '约珥看见灾难不是终点，而是悔改的呼召。他预言：我要将我的灵浇灌凡有血气的。五旬节那天，预言成真。', '珥1-3', '主，约珥的话语是复兴的邀请。帮助我在任何困境中都看见你呼召我回转的声音。求你浇灌你的灵。阿们。', true),
    (132, '阿摩司', 'Amos', '王国时代', '先知', NULL, '正面', '为社会公义勇敢发声', '牧羊人先知，在北国最繁荣时期发出社会公义的呼声，警告在虚假宗教下的不公义。', '阿摩司不是专业先知，是牧羊人。但他听见神的呼召，毫不畏惧地对权贵说：你们欺压穷人，这些我都看见了。', '摩1-9', '主，阿摩司从牧场被呼召去传讲公义。帮助我在我所在的岗位上，为你的公义发出声音。阿们。', true),
    (134, '弥迦', 'Micah', '王国时代', '先知', NULL, '正面', '行公义好怜悯谦卑与神同行', '先知，预言弥赛亚从伯利恒出生，提出了信仰最精华的总结：行公义、好怜悯、谦卑与神同行。', '弥迦把复杂的宗教律法归纳为三点：公义、怜悯、谦卑。这是圣经对信仰最简洁有力的定义。', '弥1-7', '主，弥迦6:8是你对我最清晰的期望。今天帮助我把这三件事活出来。阿们。', true),
    (135, '那鸿', 'Nahum', '王国时代', '先知', NULL, '正面', '神的公义必然到来', '先知，宣告尼尼微（约百年后再次堕落）的最终审判，见证神公义的必然性。', '尼尼微在约拿的时代悔改了，但一百年后重新走向骄傲和残忍。那鸿说：神的忍耐有终点，公义终将到来。', '鸿1-3', '主，那鸿告诉我你的公义是真实的。帮助我在受到不公义时信靠你的时间表。阿们。', true),
    (136, '哈巴谷', 'Habakkuk', '王国时代', '先知', NULL, '正面', '在疑惑中仍持守信心', '先知，勇于向神质问不公义，得到神的回应，最终宣告：即使无花果树不开花，我仍要靠神喜乐。', '哈巴谷问神：你为什么不管这些不公义？神回答了，但不是他期待的答案。他仍然选择相信。这是最诚实也最成熟的信仰。', '哈1-3', '主，哈巴谷带着所有的疑问仍然说：我要靠神喜乐。帮助我在最看不见你的时候，仍然选择喜乐。阿们。', true),
    (137, '西番雅', 'Zephaniah', '王国时代', '先知', NULL, '正面', '在患难中寻求神', '先知，宣告审判同时呼召以色列在主的日子临到前寻求神，以谦卑和公义为避难所。', '他警告审判将到，却也说：在主降怒之前要寻求祂。紧迫性与希望并存的呼召。', '番1-3', '主，西番雅呼召百姓在你的日子临到前先来寻求你。今天我来到你面前，谦卑我自己。阿们。', true),
    (138, '哈该', 'Haggai', '被掳归回时代', '先知', NULL, '正面', '先求神的国不优先自己的安逸', '先知，督促被掳归回的百姓优先重建圣殿而非各自建造自己的华美房屋，是神国优先的呼召。', '百姓归回后花十六年建自己的家，却没有建神的殿。哈该说：你们自己住有板的房屋，这殿却荒凉。他的话在一个月内让百姓开始重建。', '该1-2', '主，哈该问：这殿为何荒凉？帮助我检视我的生活优先次序，不让神的事排在我个人安逸之后。阿们。', true),
    (139, '撒迦利亚', 'Zechariah', '被掳归回时代', '先知', NULL, '正面', '靠圣灵得胜不靠才力', '异象先知，鼓励被掳归回的百姓重建圣殿，预言弥赛亚骑驴进耶路撒冷，传递靠圣灵得胜的信息。', '最著名的一句话：不是靠势力，不是靠才能，乃是靠我的灵。这是神给面对比自己更大任务的人的话。', '亚1-14', '主，你说：不是靠势力，不是靠才能，乃是靠我的灵。帮助我在今天的每件事上如此倚靠。阿们。', true),
    (140, '玛拉基', 'Malachi', '被掳归回时代', '先知', NULL, '正面', '归回神忠心奉献', '旧约最后一位先知，呼召百姓归回神、诚实奉献十分之一，预言以利亚式先知的再来。', '玛拉基是旧约最后的声音：归回我，我就归回你们。神仍然在等待。然后是四百年的沉默，直到约翰出现。', '玛1-4', '主，玛拉基是最后的归回邀请：归回我，我就归回你们。今天我选择归回。阿们。', true),
    (141, '沙得拉、米煞、亚伯尼歌', 'Shadrach, Meshach, Abednego', '王国时代', '其他', NULL, '正面', '绝对忠心即使在火窑中', '三位希伯来少年拒绝跪拜金像，被投入火窑，神与他们同在，毫发无伤。', '他们说：我们的神能救我们。即便祂不救，我们也不跪拜你的金像。这个「即便」是信仰历史上最勇敢的话之一——忠心不建立在神必定拯救的保证上。', '但3', '主，三位少年说：即便祂不救，我们也不跪拜。帮助我的信仰不以你的拯救为条件，因你是神就愿意顺服。阿们。', true),
    (142, '雅亿', 'Jael', '士师时代', '女性', NULL, '正面', '关键时刻的勇敢行动', '以色列妇女，在士师底波拉带领以色列得胜时，用帐棚橛子杀死了敌军将领西西拉，成就了底波拉的预言。', '雅亿没有军事训练，只有手中的帐棚橛子。但她看见了时机，知道这是神的时刻，她行动了。神使用平凡的人和平凡的工具，成就不平凡的事。', '士4-5', '主，雅亿提醒我：神使用有胆量行动的普通人。帮助我识别你预备的时机，然后勇敢地用手中现有的工具行动。阿们。', true),
    (143, '亚比该', 'Abigail', '王国时代', '女性', NULL, '正面', '智慧与调解化解冲突', '拿八的妻子，在丈夫因愚顽激怒大卫时，凭着智慧和主动出面阻止了大卫的报复，后来成为大卫的妻子。', '亚比该的智慧不只是聪明，而是以神的视角看问题。她说：不要让大卫因报复而玷污自己的良心。她同时保护了大卫、丈夫，和她的家。真正的智慧是三赢的。', '撒上25', '主，亚比该的智慧既谦卑又有力。帮助我在冲突中不袖手旁观，有勇气出面，用你的智慧化解危机。阿们。', true),
    (144, '户勒大', 'Huldah', '王国时代', '女性', NULL, '正面', '女性忠心传递神话语', '女先知，约西亚王命人去查问神的意思时，祭司们找到了户勒大，她忠实传达了神对律法书的确认和对约西亚的应许。', '当找到律法书时，约西亚派人去查问神的意思——他们找到了一位女先知。户勒大不是因为是女性而被选，她被选是因为她是神的先知。神在历史最关键时刻使用了她。', '王下22', '主，户勒大在历史最关键的时刻传递了你的话语。帮助我也在神托付我的位置上，忠心传递你的信息。阿们。', true),
    (145, '比撒列', 'Bezalel', '出埃及时代', '其他', NULL, '正面', '用才干和技艺荣耀神', '会幕建造者，神充满他以圣灵，赐他智慧、聪明和各样技艺，建造圣殿器具，是用艺术和工艺事奉神的先驱。', '比撒列是圣经第一位被说明被圣灵充满的人——不是为了传道，而是为了建造艺术和工艺品。这告诉我们：技艺和才干也可以被圣灵充满，也可以是神圣的。', '出31，出35-36', '主，比撒列告诉我：技艺也可以被圣灵充满。帮助我把我最好的才干奉献给你。阿们。', true),
    (146, '示巴女王', 'Queen of Sheba', '王国时代', '女性', NULL, '正面', '寻求智慧不远千里', '远从示巴来寻访所罗门、探索真智慧的女王，耶稣称赞她将在审判时为这世代作见证。', '她听见所罗门的名声，不满足于道听途说，亲自远行来查验。她带着疑问来，离开时说：所告诉我的还不到一半。真正的智慧使人谦卑。耶稣说她将起来定这世代的罪——因为她寻求了。', '王上10', '主，示巴女王不远千里来寻求智慧。帮助我不满足于间接的认识，主动地寻求你，直到我能说：所告诉我的还不到一半。阿们。', true),
    (147, '约拿单', 'Jonathan', '王国时代', '其他', NULL, '正面', '真友谊胜过个人利益', '扫罗之子，本应继承王位，却与大卫立约，保护他免于父亲的杀害，是舍己友情的典范。', '约拿单本是王位继承人，但他看见神在大卫身上的拣选，选择支持大卫而非自己的利益。他说：我爸爸的心意我比你更清楚，我要帮助你。真友谊建立在神的旨意上，不在个人利益上。', '撒上18-20', '主，约拿单的友谊是圣经最美的图画之一。帮助我成为那种在朋友最需要时愿意牺牲自己利益的人。阿们。', true),
    (148, '五饼二鱼的男孩', 'Boy with Five Loaves', '新约时代', '其他', NULL, '正面', '把所有的交给耶稣', '一个无名男孩，将五个大麦饼和两条鱼交给耶稣，成就了喂饱五千人的神迹。', '门徒看见五千人说：没有足够的食物。那男孩把他所有的五个饼和两条鱼全给出去了。不是一半，不是留下一点保险。耶稣拿了、祝谢了、分给众人。小的全部交出，在神手中成为超过需要的。', '约6', '主，那男孩把所有的给了你。帮助我不只给出一部分，而是把手中的一切全部放在你手里，相信你能成倍地使用。阿们。', true),
    (149, '寡妇的两个小钱', 'Widow''s Two Coins', '新约时代', '女性', NULL, '正面', '全部的奉献胜过部分的余剩', '圣殿中投入两个小钱的穷寡妇，被耶稣称赞她比所有富人投入更多，因为她投入了全部的生活费。', '富人们投入了剩余，她投入了全部。耶稣把门徒叫来，特别指出这一刻。他没有评论任何一位富人的奉献，却专门赞美这位没有名字的寡妇。神衡量的是比例，不是数量。', '可12，路21', '主，那寡妇的两个小钱比所有富人的更多。帮助我奉献的动机不是剩余，而是信靠你会供应。阿们。', true),
    (150, '被洁净的麻疯病人', 'Healed Leper', '新约时代', '其他', NULL, '正面', '感恩是回应恩典的第一步', '十个麻疯病人被耶稣洁净，只有一个回来俯伏在耶稣脚前感谢，而且他是撒玛利亚人。', '十个人同样被洁净，九个继续走，一个回来俯伏在耶稣脚前感谢。耶稣说：另外九个在哪里？感恩不只是礼貌，而是认识恩典来源的信仰行为。他回来，是因为他知道是谁洁净了他。', '路17', '主，那一个回来的撒玛利亚人提醒我：感恩不是附加品，而是信仰的核心。帮助我成为那回来的一个。阿们。', true),
    (151, '那路加福音的悔改税吏', 'Penitent Tax Collector', '新约时代', '其他', NULL, '正面', '谦卑认罪得蒙神悦纳', '在耶稣的比喻中，一位税吏只是捶胸祷告：神啊，开恩可怜我这个罪人，被宣告比法利赛人更为神所悦纳。', '法利赛人详细列举他的德行；税吏只低头捶胸说：神啊，开恩可怜我这个罪人。耶稣说：这人回家去比那人更称义了。谦卑认罪是神垂听祷告的门。', '路18', '主，那税吏的祷告是最短也最真实的。今天我也只说：神啊，开恩可怜我这个罪人。阿们。', true),
    (152, '撒该', 'Zacchaeus', '新约时代', '其他', NULL, '混合', '耶稣主动寻找失丧的人', '税吏长，因身材矮小爬上桑树看耶稣，耶稣主动邀请住在他家，他悔改还清加倍。', '撒该不是去见耶稣，他只是想看看耶稣是谁。耶稣却说：今天我必住在你家里。是耶稣先找了撒该。悔改发生在耶稣的主动寻找和临到之后。', '路19', '主，耶稣先找了撒该，不是等他改变好了再来。谢谢你主动寻找我。帮助我像撒该一样，在你的临到之后有真实的改变。阿们。', true),
    (153, '好撒玛利亚人', 'Good Samaritan', '新约时代', '其他', NULL, '正面', '邻舍就是眼前有需要的人', '在耶稣比喻中，一个撒玛利亚人看见被打劫的受伤者，自掏腰包付出时间和金钱帮助他，成为「爱邻如己」的定义。', '祭司和利未人看见了走过去；撒玛利亚人看见了，就动了慈心。同样看见，选择不同。爱不是感情，是行动。好撒玛利亚人没有问：这人是谁？他先帮助了。', '路10', '主，好撒玛利亚人动了慈心然后行动。帮助我不只是在感情上同情，而是在行动上帮助眼前有需要的人。阿们。', true),
    (154, '迷失的羊/儿子', 'Lost Sheep / Prodigal Son', '新约时代', '其他', NULL, '正面', '神主动寻找失丧的人', '耶稣的三个比喻（失羊、失钱、浪子）共同描述神主动寻找失丧之人的喜乐，浪子回头是最著名的悔改图像。', '浪子「醒悟过来」——他想到父亲的家，然后就起身回去。父亲远远看见他就跑过去。神不是坐在那里等你走完全程，而是在你转身的时候就已经跑向你。', '路15', '主，浪子醒悟过来就起身回去，你就跑向他。谢谢你在我还在远处就已经跑来。今天我也起来回到你面前。阿们。', true),
    (155, '伯大尼的抹香妇人', 'Sinful Woman with Perfume', '新约时代', '女性', NULL, '正面', '蒙大赦免则有大爱', '一个有罪名的女人，在法利赛人家中用眼泪和香膏膏抹耶稣的脚，耶稣称赞她：她许多的罪都赦免了，因为她的爱多。', '法利赛人心里说：这人若是先知，就必知道摸他的是谁。耶稣却对那女人说：你的罪赦免了，你的信救了你。她的爱多，因为她知道自己被赦免了多少。深知自己需要恩典的人，才能有最深的爱。', '路7', '主，那女人的眼泪和香膏是对你的最美告白。帮助我深知自己蒙赦免的多，让这知识转化为对你的爱。阿们。', true),
    (156, '以利沙', 'Elisha', '王国时代', '先知', NULL, '正面', '双倍的圣灵与日常的服事', '以利亚的继承人，求双倍的灵，行了比以利亚更多的神迹，并在临死前仍有先知的能力。', '以利沙求的不是权力或名声，而是双倍的灵。他的神迹——斧头浮在水面、死孩子复活、麻疯人洁净——发生在他与普通人的日常互动中。神迹不只在山顶，也在厨房和田野。', '王下2-13', '主，以利沙求双倍的灵。帮助我对圣灵的渴慕超过对任何其他事物的渴慕。让我的生命也是神迹发生的地方。阿们。', true),
    (157, '约拿单的儿子米非波设', 'Mephibosheth', '王国时代', '其他', NULL, '正面', '恩典接纳最不配的人', '约拿单残疾的儿子，大卫为了与约拿单的盟约主动找到他，让他在王的桌前吃饭，如同王子。', '米非波设说：我算什么，不过是一条死狗。但大卫说：你要常在我桌前吃饭。这是恩典的图画：不是因为他配，而是因为盟约。这正是神对我们的写照。', '撒下9', '主，米非波设认为自己是条死狗，你却让他坐在王的桌前。谢谢你因着你的盟约接纳我。帮助我谦卑地坐在你桌前。阿们。', true),
    (158, '所罗门后期', 'Solomon in His Decline', '王国时代', '君王', '统一王国', '警戒', '智慧不能保护不顺服的心', '所罗门晚年因许多外邦妻子转离神，心不专一，是有史以来最大的智慧被最小的试探所败的案例。', '他有最大的智慧，写了传道书的虚空，却仍然被女人和舒适逐渐带离神。神向他显现两次，他仍然偏离。这告诉我们：智慧本身不能代替顺服；知识而没有委身是危险的。', '王上11', '主，所罗门的结局警告我：最大的恩赐不能保证最后的忠心。帮助我不只是聪明，而是真正地顺服你。阿们。', true),
    (159, '耶洗别', 'Jezebel', '王国时代', '女性', NULL, '警戒', '控制操纵的属灵危险', '北国王后，极力推广巴力崇拜，杀害先知，操纵亚哈王，是圣经中权力操纵和属灵腐蚀的最典型案例。', '耶洗别从不直接动手，她用操纵、伪造文书、利用亚哈的权力。她让拿伯死，让巴力兴盛。启示录用她的名字形容导人远离神的教训。操纵比明显的恶更难识别，也更危险。', '王上18-21，王下9', '主，耶洗别的操纵提醒我：影响力可以用来服事神也可以用来腐蚀信仰。帮助我检视我影响他人的动机和方式。阿们。', true),
    (160, '迦勒', 'Caleb', '出埃及时代', '其他', NULL, '正面', '专心跟随神到底', '十二探子之一，与约书亚两人坚持进入迦南，四十年后八十五岁仍然要求山地，是终生忠心的典范。', '神说迦勒有「另一个心志」，他专心跟从我。四十五年后，85岁的迦勒说：神应许给我的山地，现在将它给我。仍然在跑。年岁不能熄灭这种火。', '民14，书14', '主，迦勒85岁仍然在跑，仍然在要山地。帮助我的信仰不随年龄或等待而冷却，专心跟随你到底。阿们。', true),
    (161, '巴拿巴', 'Barnabas', '新约时代', '其他', NULL, '正面', '鼓励的恩赐成就他人的使命', '被称为劝慰之子，出卖田地奉献，接纳刚悔改的扫罗，发掘了保罗，甘心退到第二线成就他人。', '在所有人都怀疑保罗时，巴拿巴带他去见使徒，用自己的信誉为他担保。后来保罗的使命超越了他，他不嫉妒，他甘心为保罗铺路。最好的领袖培养出比自己更好的人。', '徒4，徒9，徒11-15', '主，巴拿巴用他的信誉帮助保罗，然后甘心退后。帮助我也愿意成就比我更有才能的人，而非保护我的位置。阿们。', true),
    (162, '十字架上的强盗', 'Penitent Thief', '新约时代', '其他', NULL, '正面', '最后一刻的悔改也被神接受', '在十字架上，一个强盗在生命的最后时刻向耶稣祈求：你进入你的国时，求你记念我。耶稣回答：今日你要同我在乐园里了。', '他没有时间做任何善事，没有机会受洗，没有机会补偿。他只有一个呼求：记念我。耶稣说：今日——不是以后，不是等你做了什么——今日你要同我在乐园里了。这是最彻底的恩典。', '路23', '主，你对那强盗说：今日。这是最彻底的恩典——不是以后，不是等我改好了。谢谢你在最后一刻也接受悔改的人。阿们。', true),
    (163, '抹大拉的马利亚', 'Mary Magdalene', '新约时代', '女性', NULL, '正面', '被解救者成为最忠心的见证人', '从她身上赶出七个鬼，此后一直跟随耶稣，在十字架和空坟墓旁都在场，是第一个复活见证人。', '她在耶稣最孤单的时刻都在——十字架下、坟墓旁。复活的早晨，她去找耶稣，耶稣叫她的名字：马利亚。被呼唤名字的那一刻，她认出了他。被爱改变的人是最忠心的见证者。', '路8，约20', '主，你叫了马利亚的名字，她立刻认出了你。谢谢你也知道我的名字。帮助我像她一样成为你复活的忠心见证人。阿们。', true),
    (164, '司提反', 'Stephen', '新约时代', '其他', NULL, '正面', '为信仰殉道的见证', '首位殉道者，被石头打死时看见天开、人子站在神右边，临死为仇敌祷告，间接影响了扫罗的悔改。', '他们打石头打他，他跪下大声说：主，不要将这罪归于他们。然后就睡了。这祷告可能是保罗归主旅程的第一根线。一个人的死，改变了另一个人的方向，影响了整个外邦世界。', '徒6-7', '主，司提反临死为仇敌祷告。帮助我在被冤枉或受苦时，仍然能为那些伤害我的人祷告，相信你能使用我的见证。阿们。', true),
    (166, '约伯的妻子', 'Job''s Wife', '族长时代', '女性', NULL, '警戒', '苦难中的绝望与放弃', '约伯最深苦难中，他的妻子对他说：你弃掉神死了吧，成为信仰危机中最极端的绝望呼声。', '她的话出现在约伯苦难最深处。我们不知道她完整的故事——她也失去了孩子，也在受苦。但她的回应是绝望的放弃。苦难可以叫人弃掉信仰，也可以叫人更深地抓住神。约伯拒绝了她的建议。', '伯2', '主，约伯拒绝了绝望的建议，仍然信靠你。帮助我在最深的苦难中不放弃你，也帮助我的话成为别人信仰的支柱而非绊脚石。阿们。', true),
    (167, '以利法、比勒达、琐法', 'Eliphaz, Bildad, Zophar', '族长时代', '其他', NULL, '警戒', '错误的安慰比沉默更伤人', '约伯三个朋友，最初七天无声陪伴，后来用错误的神学归咎约伯，神最终说他们说的不对。', '他们最好的时刻是前七天：无声坐在地上，因为看见约伯的痛苦极大。然后他们开口了，用「你一定犯了罪」来解释苦难。神说：你们议论我的不如我的仆人约伯。知识而没有谦卑，伤人比帮助更多。', '伯3-37', '主，三个朋友的前七天是最好的陪伴，然后他们开口了。帮助我在别人受苦时先无声同在，不急于解释。阿们。', true),
    (168, '基甸的三百人', 'Gideon''s Three Hundred', '士师时代', '其他', NULL, '正面', '神能以少胜多', '神将基甸的军队从三万二千人削减到三百人，然后以号角和瓦器罐打败了米甸大军。', '神说：人多了，我不能将米甸交在他们手里。然后一削再削，直到三百人。这三百人不因少数而退缩，他们拿的武器是号角和瓦器，不是刀剑。神要的不是你的能力，是你的顺服。', '士7', '主，三百人打败了大军。帮助我不因力量的削减而灰心，而是更多地倚靠你。阿们。', true),
    (169, '约阿施', 'Joash', '王国时代', '君王', '南国犹大', '混合', '属灵成长需要持续的属灵引导', '幼年在圣殿被保护，在祭司耶何耶大辅导下行正道，耶何耶大死后却转向败坏，甚至杀害其子撒迦利亚。', '他在耶何耶大的保护和辅导下行神眼中看为正的事。耶何耶大死了，他立刻转向。这显示属灵生命必须真正内化，而非只依靠外在辅导。依赖属灵权柄而非真正委身神，会在那人消失时崩溃。', '王下12，代下24', '主，约阿施的悲剧在于他的信仰是借来的。帮助我的信仰是真正我自己的——深入内心，不依赖任何人的存在而支撑。阿们。', true),
    (170, '以西结', 'Ezekiel', '王国时代', '先知', NULL, '正面', '异象激励在黑暗中的盼望', '被掳先知，在巴比伦以异象、行动预言和枯骨复生的图像，传达神对以色列复兴的应许。', '他在最灰暗的地方接受最大的异象：枯骨满谷的异象——神问：这些骸骨能复活吗？他回答：主耶和华啊，你是知道的。神在绝望的废墟上建立盼望。枯骨能复活，是最大的信仰宣言。', '结1-48', '主，以西结在枯骨满谷中宣告复活的异象。帮助我在我最绝望的领域仍然相信你能叫枯骨复活。阿们。', true),
    (171, '以斯拉', 'Ezra', '被掳归回时代', '祭司', NULL, '正面', '归回神话语的复兴', '文士祭司，带领以色列人归回后宣读律法书，带动属灵复兴，也严肃处理以色列人娶外邦妻的问题。', '以斯拉读律法书，众民都哭了。然后他说：今日是圣日，不要悲伤，以神为乐是你们的力量。他公开读神的话，带来了眼泪，然后带来了喜乐。话语的能力同时带来认罪和祝庆。', '拉7-10', '主，以斯拉用你的话语带来了眼泪和喜乐。帮助我认真对待你的话语，让它在我心里带来真实的复兴。阿们。', true),
    (172, '拿俄米', 'Naomi', '士师时代', '女性', NULL, '混合', '苦难中的诚实与恩典的意想不到', '失去丈夫和两个儿子的寡妇，苦到叫百姓叫她「苦」，却成为路得信仰的桥梁，波阿斯的姻亲。', '她说：不要叫我拿俄米，要叫我玛拉（苦），因为全能者使我受了大苦。这是圣经最诚实的信仰陈述之一。她没有假装没事，但神在她的苦中仍然工作。诚实的苦，是走向恢复的开始。', '得1-4', '主，拿俄米诚实地说：你让我受了大苦。谢谢你不要求我假装没事。帮助我在诚实的苦中仍然看见你的工作。阿们。', true),
    (173, '施洗约翰', 'John the Baptist', '新约时代', '先知', NULL, '正面', '为基督铺路甘心减少', '预备主道的先知，宣告基督的来到，当众人跟随耶稣而非他时，说：我必须减少，他必须增加。', '他的门徒跑来说：所有人都去跟那人了。他回答：朋友的客听见新郎的声音就甚喜乐，这就是我的喜乐，是满足的。我必须减少。没有被取代的苦涩，只有使命完成的满足。', '太3，约1，约3', '主，约翰说：我必须减少，他必须增加。帮助我也以这句话作为我事奉和生命的心志。阿们。', true),
    (174, '彼得岳母', 'Peter''s Mother-in-law', '新约时代', '女性', NULL, '正面', '被医治后立刻服事', '彼得岳母发烧被耶稣治好，立刻起来服事众人，是「被医治后立即服事」最简洁的图画。', '耶稣拉她的手，她立刻起来服事众人。没有休息，没有犹豫。被恩典触摸的自然反应就是服事。这是信仰最简单的循环：接受恩典→起来→服事。', '可1，太8，路4', '主，彼得岳母被医治就立刻服事。帮助我不把你的恩典留给自己，而是让它立刻转化为对他人的服事。阿们。', true),
    (175, '安得烈', 'Andrew', '新约时代', '其他', NULL, '正面', '带人来见耶稣的事奉', '彼得的兄弟，第一件事就是去找彼得说：我们遇见了弥赛亚，然后把他带来见耶稣。', '安德烈不是最著名的使徒，彼得更有名。但彼得来见耶稣是因为安德烈带他去的。还有那男孩的五饼二鱼，是安德烈带来的。还有外邦人要见耶稣，是安德烈和腓力报告的。他总是在「把人带到耶稣面前」。', '约1，约6，约12', '主，安德烈每次出现都在把人带到你面前。帮助我也成为这样的人：不需要舞台，只要把人带来见耶稣。阿们。', true),
    (177, '多马', 'Thomas', '新约时代', '其他', NULL, '混合', '从怀疑到最深的信仰告白', '被称为怀疑的多马，但也是第一个在复活耶稣面前说出「我的主，我的神」的门徒。', '他说除非我亲眼看见、亲手摸见，我不信。耶稣没有拒绝他，而是专门为他显现。然后多马说出了圣经中最深刻的信仰告白：我的主，我的神。最深的疑惑，可以产生最深的信仰。', '约11，约14，约20', '主，多马的疑惑换来了最深的告白：我的主，我的神。帮助我也把所有的疑惑带到你面前，让它成为更深认识你的机会。阿们。', true),
    (178, '革妈利', 'Gamaliel', '新约时代', '其他', NULL, '正面', '智慧辨别神的工作', '犹太公会的法利赛教法师，在审判使徒时建议：若是出于人，必然消散；若是出于神，你们就不能消灭他们。', '他是保罗的老师，又是严格的法利赛人，却在最重要的时刻说出了最有智慧的话。他没有信主，但他承认无法判断神的工作。有时候最大的智慧是说：我不知道，我等着看。', '徒5', '主，革妈利的智慧在于他说：若是出于神，你们就不能消灭他们。帮助我在面对不确定的事时，有谦卑等候的智慧。阿们。', true),
    (179, '百夫长哥尼流', 'Cornelius', '新约时代', '其他', NULL, '正面', '寻求神的外邦人蒙神垂听', '罗马百夫长，虔诚敬畏神，常常祷告施舍，神差天使指示他差人去找彼得，成为外邦人领受圣灵的第一个里程碑。', '他是外邦人，没有接受割礼，但他的祷告和施舍在神面前留为记念。神主动打开了他接受福音的门。你不必完全了解神才能寻求神——寻求的人，神会主动来到。', '徒10', '主，哥尼流的祷告和施舍在你面前留为记念。帮助我的每日生活也是对你真实的寻求，相信你会主动来到。阿们。', true),
    (180, '以哥念的一个女门徒大比大', 'Tabitha (Dorcas)', '新约时代', '女性', NULL, '正面', '服事的生命留下不可磨灭的印记', '约帕城的女门徒，专心行善事和周济穷人，死后彼得为她祷告，她复活，许多人因此信主。', '她死了，寡妇们把她缝的衣服都带来给彼得看——这是她留下的生命见证。不是话语，是衣服。实际的爱是最有力的见证。她的复活使许多人信主——她的服事在死后仍然在传福音。', '徒9', '主，大比大的生命见证是那些衣服——具体的爱。帮助我的信仰也以具体的善行留下印记，而非只是话语。阿们。', true),
    (181, '腓利门', 'Philemon', '新约时代', '其他', NULL, '正面', '饶恕超越社会结构', '保罗的朋友，保罗写信请他接回逃跑的奴隶阿尼西谋，不再以奴隶待他，而是以弟兄接纳。', '保罗说：你若以我为同伴，就收纳他，如同收纳我一样。这是一封要求一个有权力的人放弃权力去接纳的信。腓利门接受了这封信，就已经选择了接受这个要求。真正的饶恕改变关系的本质。', '腓利门书', '主，保罗请腓利门接纳阿尼西谋如同接纳他自己。帮助我也愿意接纳曾经伤害我的人，不再以旧的身份定义他们。阿们。', true),
    (182, '百基拉与亚居拉', 'Priscilla and Aquila', '新约时代', '其他', NULL, '正面', '夫妻同心共同服事', '帐棚制造的夫妇档，在各地接待保罗，开放家作教会，私下教导了亚波罗，是事奉神国的夫妻团队典范。', '他们不是长老，没有重要头衔，是做帐棚的。但每次出现，都是在服事福音——开放家作教会、私下教导有才华但教义不完全的亚波罗。他们的家就是神国的工具。', '徒18，罗16，林前16', '主，百基拉和亚居拉把家变成神国工具。帮助我也愿意开放我所有的来服事你的国度。阿们。', true),
    (183, '雅各（耶稣兄弟）', 'James the Lord''s Brother', '新约时代', '其他', NULL, '正面', '从不信到领袖的蜕变', '耶稣的兄弟，复活前不信耶稣，复活后遇见耶稣，成为耶路撒冷教会领袖，写下雅各书，殉道。', '他在耶稣传道期间被称为「连他的兄弟也不信他」的家人之一。然后耶稣复活，专门向他显现（林前15:7）。他接下来成为耶路撒冷教会的柱石。最熟悉的关系也可以成为最深的信仰关系。', '可3，约7，加1-2，雅1', '主，雅各从不信到成为教会柱石。帮助我为我不信主的家人继续祷告，相信你也会在他们身上工作。阿们。', true),
    (184, '拿因城的寡妇', 'Widow of Nain', '新约时代', '女性', NULL, '正面', '耶稣主动向悲伤的人表达怜悯', '小拿因城寡妇独子的葬礼上，耶稣没有被邀请，却主动停下来，怜悯她，叫她的儿子从死里复活。', '耶稣看见她，就动了慈心，对她说：不要哭。他没有被邀请，没有人向他祈求。他主动停了下来，因为他「看见了」她。神看见你最深的悲哀，即使你没有开口求告。', '路7', '主，你没有被邀请，却主动停下来怜悯那寡妇。谢谢你在我还没开口时就已经看见我的眼泪。阿们。', true),
    (185, '西门（古利奈人）', 'Simon of Cyrene', '新约时代', '其他', NULL, '正面', '被迫背负的十字架成为属灵的呼召', '从乡下进城的人，被罗马兵丁强迫帮耶稣背十字架，他的儿子亚力山大和鲁孚后来成为教会成员。', '他是被迫的，不是自愿的。他从乡下进城，被随机拉来背十字架。但他的两个儿子亚力山大和鲁孚后来成为了信徒（被马可提名，说明读者认识他们）。一个被迫的行动，改变了一个家庭的属灵历史。', '可15，太27，路23', '主，西门被迫背起十字架，却因此成了历史的一部分。帮助我接受那些被迫的担子，相信你能用意想不到的方式翻转它们。阿们。', true),
    (186, '拿单先知', 'Nathan the Prophet', '王国时代', '先知', NULL, '正面', '以智慧说出真话的勇气', '大卫的先知，为大卫传达建殿的应许，又在大卫犯罪后以比喻指出大卫的罪，是说真话的先知典范。', '大卫是王，拿单是先知。拿单没有直接说：你犯罪了。他说了一个故事：有一个富人抢了穷人的羊。大卫愤怒，拿单说：你就是那人。智慧是以让人自己看见的方式说出真相。', '撒下7，撒下12', '主，拿单以智慧和勇气向大卫说真话。帮助我在需要说真话时有智慧地说出来，不为讨好人，不为伤害人，只为说神的话。阿们。', true),
    (187, '乌西雅', 'Uzziah', '王国时代', '君王', '南国犹大', '警戒', '骄傲在成功巅峰最危险', '犹大王，前半生行神眼中看为正的事，国力强盛，却在权力顶峰时擅自进入圣殿献香，因骄傲被击打生痲疯。', '成功的前半生：他寻求神，神使他亨通。代下26:5说：只要他寻求神，神使他亨通。然后一切改变了——心骄气傲。骄傲最危险的时机不是失败中，而是成功的顶峰。他不是一夜变坏，是渐渐的。', '代下26', '主，乌西雅在最成功的时候骄傲，然后败落。帮助我在成功中更加谦卑寻求你，而不是以成就代替了倚靠。阿们。', true),
    (188, '约西亚', 'Josiah', '王国时代', '君王', '南国犹大', '正面', '对神话语的谦卑带来复兴', '犹大王，八岁登基，在修殿时发现律法书，立即撕裂衣服认罪，带领全国立约归回神，是历史上最彻底的宗教改革。', '他们找到律法书，读给他听，他立刻撕裂衣服。这是一个王的谦卑反应——不是辩驳，不是解释，是认罪。然后他召集所有人，亲自在他们面前读律法，一同立约。谦卑听见神的话，是复兴的开始。', '王下22-23，代下34-35', '主，约西亚听见你的话就撕裂衣服。帮助我也以这样谦卑的心来到你的话语面前，让它真实地改变我和我周围的人。阿们。', true),
    (189, '押沙龙', 'Absalom', '王国时代', '其他', NULL, '警戒', '用魅力和苦毒建造的权力必然崩溃', '大卫之子，因妹妹他玛被强暴后父亲不处理，心生苦毒，最终用魅力夺取人心、发动政变，败亡于树林中。', '他站在城门口帮助来投诉的人，说：你的事有理，只可惜没有人替你申冤——偷取人心是有预谋的魅力政治。苦毒未处理，转化成了政治操纵。魅力和魅力政治，都会在终点被树枝挂住。', '撒下13-18', '主，押沙龙的苦毒摧毁了自己和他的家庭。帮助我今天处理心里的苦毒，不让它在黑暗中发酵成为更大的破坏。阿们。', true),
    (190, '俄巴底亚', 'Obadiah', '王国时代', '其他', NULL, '正面', '在险境中暗中保护神的仆人', '亚哈王家宰，暗中藏匿了一百个先知，保护他们免于耶洗别的杀害，是黑暗时代的秘密守护者。', '耶洗别杀先知，俄巴底亚藏了一百人在山洞里供应食物和水。他没有公开对抗，他用自己的位置做能做的事。不是所有的勇气都是公开的宣告——有些勇气是安静的保护。', '王上18', '主，俄巴底亚安静地保护了一百个先知。帮助我也愿意用我所在的位置，安静地服事和保护那些需要帮助的人。阿们。', true),
    (191, '以利亚的仆人', 'Elijah''s Servant', '王国时代', '其他', NULL, '正面', '持续等候直到神应许成真', '在迦密山祷告求雨后，以利亚七次差遣仆人去看海面，仆人每次都回来报告，直到第七次看见一小片云彩。', '六次：没有什么。仆人没有放弃，以利亚没有停止祷告。第七次：有一片云彩如人的手那么小。然后大雨倾盆。信仰的坚持：在六次看不见后，仍然去第七次。结果从一小片云开始。', '王上18', '主，那仆人去了七次。帮助我在六次看不见之后，仍然有信心去第七次，因为你的应许必然成就。阿们。', true),
    (192, '撒母耳的母亲哈拿', 'Hannah', '士师时代', '女性', NULL, '正面', '在痛苦中向神倾诉并交托', '不能生育的女人，在圣殿哭泣祷告，许愿将孩子归还给神，神垂听她，她生了撒母耳，守住了她的誓言。', '她在神面前痛哭，诉说心里的苦情。祭司以利以为她喝醉了。她说：我没有喝酒，是心里愁苦在神面前倾心吐意。神垂听了眼泪的祷告。她许愿：若赐我孩子，我将他归还给你。然后她真的做到了。', '撒上1-2', '主，哈拿在你面前痛哭，你垂听了她的眼泪。帮助我也把我最深的痛苦带到你面前，相信你看见并垂听。阿们。', true),
    (193, '约拿（先知）', 'Jonah', '王国时代', '先知', NULL, '混合', '神的怜悯大过先知的期待', '逃避神呼召的先知，被大鱼吞了三天，转回去传讲审判，尼尼微人悔改，他却因神饶恕城市而发怒。', '他宁愿死也不愿看到仇敌蒙恩典。这是信仰最黑暗的角落——用神的名义，实际是为自己的偏见服务。神问他：你为那葫芦发怒合理吗？约拿说：合理。神说：尼尼微那么多人，我岂能不爱惜？', '拿1-4', '主，约拿的故事提醒我：神的怜悯不限于我的圈子。帮助我打开心去接受你对所有人的爱，包括那些我不容易爱的人。阿们。', true),
    (194, '喇合', 'Rahab', '进入迦南时代', '女性', NULL, '正面', '信心超越背景的蒙恩典', '耶利哥的妓女，藏匿以色列探子，以红绳为标志，全家得救，进入以色列民，成为大卫和耶稣的祖先。', '她说：我知道耶和华已经把这地给了你们，我们因你们甚是惊惧。她的信心来自她所听见的。她不是以色列人，她是妓女，但她相信，她行动，她的行动是信心的见证。来11:31说：喇合接待探子没有和那些不顺从的人一同死亡。', '书2，书6，来11', '主，喇合是妓女，却进入了耶稣的家谱。谢谢你不用我的背景来定义我的未来。帮助我今天用行动表达我的信心。阿们。', true),
    (195, '耶罗波安', 'Jeroboam', '王国时代', '君王', '北国以色列', '警戒', '以政治考量替代神的心意', '北国以色列第一王，神应许他的王朝，他却因政治考量设立金牛犊，被称为「使以色列陷入罪中的耶罗波安」。', '神给他承诺，条件是顺服。他不信任百姓去圣殿会转向大卫家，于是在伯特利和但各立一个金牛犊说：以色列啊，这是领你出埃及的神。政治考量打败了信仰顺服。他的名字成了一个模式：北国二十个王，每一个都「行耶罗波安的道」。', '王上12-13', '主，耶罗波安用政治考量代替了对你的顺服。帮助我在决策中不以方便和稳定作为第一考量，而是真正地寻求你的旨意。阿们。', true),
    (196, '亚波罗', 'Apollos', '新约时代', '其他', NULL, '正面', '才华与谦卑接受纠正的组合', '亚历山大来的能言善辩者，精通圣经，热心讲道，却只知约翰的洗礼；接受百基拉和亚居拉私下教导后，成为更有力的传道者。', '他有才华、有热情、有圣经知识——但不完全。百基拉和亚居拉私下把神的道给他讲解更加详细，他接受了。才华加上谦卑接受纠正，是最有力的组合。才华而不接受纠正，是危险的；谦卑而没有才华，是有限的。两者同时，是神国最需要的。', '徒18', '主，亚波罗才华卓越却谦卑接受纠正。帮助我用你给的才干热心事奉，同时保持开放的心接受更完全的真理。阿们。', true),
    (197, '阿尼西母', 'Onesimus', '新约时代', '其他', NULL, '正面', '从逃奴到有用弟兄的蜕变', '腓利门的逃跑奴隶，在保罗狱中归主，保罗称他为「我心上的儿子」，写信请腓利门以弟兄接纳他。', '他从一个逃跑的、「无用的」奴隶，变成了保罗称为「有用的」同工。他的名字意思就是「有用的」——他终于活出了他的名字。在基督里，过去的身份不再定义你；你可以活出本名的意义。', '腓利门书，西4', '主，阿尼西谋从无用变为有用，从逃跑变为回去。帮助我也在你里面活出我本该有的生命，不再逃避，而是面对。阿们。', true),
    (198, '提摩太', 'Timothy', '新约时代', '其他', NULL, '正面', '在软弱中被塑造为信实的同工', '保罗的属灵儿子，由外祖母罗以和母亲友尼基培养信仰，天性软弱却被保罗委以重任，经历成长与塑造。', '保罗说他有「真实的信心」，先在他外祖母罗以和母亲友尼基心里。信仰的传承从家庭开始。保罗也说：你要为福音与我同受苦难。软弱的人也可以被神使用——保罗提醒他：不要因为年幼而被人轻视。', '徒16，提前，提后', '主，提摩太软弱却忠心。帮助我不以软弱为借口，而是在软弱中倚靠你的力量去做你呼召我做的事。阿们。', true),
    (199, '路司特的瘸腿人', 'Lame Man at Lystra', '新约时代', '其他', NULL, '正面', '信心使人站立而行', '生来瘸腿、从未走过的人，保罗看见他有信心，对他说：起来，两脚站直。他就跳起来行走了。', '保罗定睛看他，见他有信心可以得医治。信心不是看不见的东西——别人能看见你的信心。那人的信心在他专注聆听保罗讲道的姿态中显现。他从未走过路，却在一声「起来」后跳起来。神的话加上人的信心，产生神迹。', '徒14', '主，你对那瘸腿人说：起来，他就跳了起来。今天你也对我说起来的地方，帮助我立刻顺服而行。阿们。', true),
    (200, '约书亚', 'Joshua', '进入迦南时代', '其他', NULL, '正面', '刚强壮胆带领神的百姓前进', '摩西的继承人，带领以色列人过约旦河、攻克耶利哥、征服迦南，是以信心和顺服继承应许的典范。', '神对约书亚说了四次：刚强壮胆。这说明他是需要被激励的人，不是天生无所畏惧的英雄。他的勇气来自神的话，不是他的性格。他最后说：至于我和我家，我们必定侍奉耶和华。这是个人立场的公开宣告。', '书1-24', '主，你对约书亚说：刚强壮胆，不要惧怕。今天也对我说这话。帮助我公开地说：至于我和我家，我们必定侍奉耶和华。阿们。', true),
    (201, '亚拿女先知', 'Anna the Prophetess', '新约时代', '女性', NULL, '正面', '一生等候神应许的忠心', '八十四岁的女先知，守寡后在圣殿昼夜祷告禁食，在圣婴耶稣被带来圣殿时立即认出，向众人宣告。', '她守寡多年，没有离开圣殿，昼夜禁食祷告事奉神。七十年的等候。然后在八十四岁那年，她等候的终于出现了——她亲眼看见婴儿耶稣，立刻感谢神，向众人讲论这孩子。漫长的等候不是浪费，而是积累。', '路2', '主，亚拿等候了七十年，在圣殿昼夜事奉，然后看见了你。帮助我在等候中不荒废，而是用等候的时间昼夜事奉你。阿们。', true),
    (202, '西面（圣殿老人）', 'Simeon', '新约时代', '其他', NULL, '正面', '等候神应许直到亲眼看见', '公义虔诚的老人，圣灵启示他未死之前必能看见主的基督，婴儿耶稣被带来时他抱着他说：我可以安然去世了。', '他不知道要等多久，但他知道神的应许必然成就。当那一天来到，他抱着婴儿耶稣说：主啊，如今可以照你的话，释放仆人安然去世了。等候的终点是满足。他等了一生，只为这一刻，然后说：够了，我可以去了。', '路2', '主，西面等候了你的应许，然后说：够了，我可以安然去世了。帮助我在等候中有同样的信心，知道你的应许必然成就。阿们。', true),
    (203, '亚哈随鲁王', 'Ahasuerus', '被掳归回时代', '君王', '外邦君王', '混合', '权力在神手中被翻转', '波斯王，以斯帖记的背景君王，起初轻率废后，被哈曼操控，最终在以斯帖的智慧和神的主权下，成为拯救犹太人的工具。', '他是大帝王，但他的决定几乎都是被别人影响的——先被哈曼操控，后被以斯帖的智慧改变。圣经对他没有明显的属灵评价，但他的每个关键决定都在神的主权下服务于神的计划。神能使用任何人——即使那人不知道自己被使用。', '斯1-10', '主，你在亚哈随鲁王的决定中掌权，即使他不认识你。谢谢你的主权超越人的权力。帮助我成为传递你智慧的声音，而非操控的力量。阿们。', true),
    (204, '以利户', 'Elihu', '族长时代', '其他', NULL, '混合', '年轻的热情与有限的洞察', '约伯三友之后出现的年轻人，因不满三位老友无法回答约伯而发怒，用大量言辞为神辩护，最终被神绕过而不评论。', '他等了很久才开口，因为年轻而等候年长者先说。他的出发点是对神的热情——他真诚地想为神辩护。但他的话很多，神最后只提了约伯和三位朋友，没有提到他。热情而没有谦卑，言辞多而不到位。年轻的热心需要时间和苦难来深化。', '伯32-37', '主，以利户热情却被你绕过。帮助我的热情不只是多说，而是真正地倾听、真正地同理，说出你真正要说的话。阿们。', true),
    (206, '利亚', 'Leah', '族长时代', '女性', NULL, '混合', '在不被爱中寻求神', '雅各不爱的妻子，却接连为他生儿子，圣经描述她的每次生产都是她与神的对话，最终被葬在亚伯拉罕家族的墓地。', '她生第一个儿子说：耶和华看见了我的苦情。生第三个儿子说：这次我要赞美耶和华。她把痛苦转化为对神的倾诉，在雅各的冷落中，神一直在看见她。被人忽视不等于被神遗忘——神垂顾那些被人边缘化的人。', '创29-35', '主，利亚在不被爱中仍然转向你。帮助我在被忽视时记得你的眼睛永远看见我，把每一次痛苦都变成向你倾诉的机会。阿们。', true),
    (207, '拉结', 'Rachel', '族长时代', '女性', NULL, '混合', '深爱与不育之痛的挣扎', '雅各深爱的妻子，长期不育，终于生下约瑟，在生便雅悯时难产而死，成为以色列民族情感中最深的母亲形象。', '她的眼泪和等候是真实的。神终于垂听她开了她的胎，她生了约瑟。但她没有满足，她继续渴望，最终在生第二个儿子时离世。先知耶利米引用她的哭声来描述以色列被掳的悲痛：拉结哭她的儿女，不肯受安慰。她的形象成了代代母亲之爱的象征。', '创29-35', '主，拉结的等候和眼泪你都看见。帮助我把最深的渴望诚实地带到你面前，在等候中信靠你的时间，而非用嫉妒和抓取代替等候。阿们。', true),
    (208, '书念妇人', 'Shunammite Woman', '王国时代', '女性', NULL, '正面', '慷慨款待与坚定的信心', '一位富有的书念妇人，主动为以利沙建了一间客房，儿子死后独自去找先知，不轻易接受安慰，只要先知亲自去，结果儿子复活。', '儿子死了，她把他放在床上，对丈夫说：平安无事。然后骑驴去找先知，一路不停。当以利沙的仆人问：你好吗？她说：平安。她没有在路上崩溃，她一路保持，直到见到先知，才在他脚前哭泣。信心不是否认痛苦，而是知道去哪里找答案。', '王下4', '主，书念妇人为你的仆人建了客房，在危机中直奔你面前。帮助我有同样慷慨的心，在危机中也知道直接来到你面前。阿们。', true),
    (209, '拔示巴', 'Bathsheba', '王国时代', '女性', NULL, '混合', '从悲剧到王后的蜕变', '被大卫强取的妇人，丈夫乌利亚死后成为大卫的妻子，第一个孩子死去，后来生所罗门，最终成为为儿子争取王位的母亲。', '她是故事里最无辜的受害者——被权力强取。第一个孩子死了，是大卫罪的代价。然后她生了所罗门。在大卫晚年，她智慧地确保所罗门登基，成为母后。悲剧的入口不是结局。神在她破碎的故事里继续工作，所罗门成了最有智慧的王。', '撒下11-12，王上1-2', '主，拔示巴的故事是悲剧，但你在其中仍然工作。谢谢你不因别人对我的伤害而放弃我。帮助我也在最破碎的地方看见你继续工作。阿们。', true),
    (210, '撒罗米', 'Salome', '新约时代', '女性', NULL, '正面', '陪伴十字架与复活的女门徒', '西庇太的妻子、雅各和约翰的母亲，曾为儿子求高位，却也是站在十字架旁、第一批来到空坟墓的女人之一。', '她曾求耶稣让两个儿子坐在祂左右。耶稣说：你们不知道你们所求的是什么。然后十字架上，她站在那里。她看着儿子的师傅被钉死，仍然留下来。然后成为第一批复活见证人。从求高位到站在十字架下——这是真实的门徒成长。', '可15-16，太20', '主，撒罗米从求高位到站在十字架下。帮助我也从追求地位成长为愿意陪伴你走苦难的路，直到看见复活。阿们。', true),
    (211, '以利沙伯', 'Elizabeth', '新约时代', '女性', NULL, '正面', '在老年仍然蒙神垂听的等候', '祭司撒迦利亚的妻子，年老不育，却怀了施洗约翰；在马利亚来访时被圣灵充满，说出祝福马利亚和她腹中胎儿的话。', '她和丈夫都义人，遵行神的诫命无可指摘——但她不育，年纪老迈。神没有忘记她，只是时候未到。当马利亚来访，婴儿在她腹中跳动，她被圣灵充满说：你在妇女中是有福的！她是第一个公开宣告马利亚所怀是「主的母亲」的人。老年的等候，换来了先知的出生。', '路1', '主，伊利沙白等候了一生，你在老年给她一个先知。帮助我在漫长的等候中仍然义人无可指摘，相信你的时候必然来到。阿们。', true),
    (212, '西庇太的雅各', 'James son of Zebedee', '新约时代', '使徒', NULL, '正面', '第一位殉道的使徒', '约翰的兄弟，被耶稣呼召离网跟随，是十二使徒中第一个为信仰殉道的，被希律亚基帕杀死。', '他和弟弟约翰曾被称为「雷子」，也曾求耶稣让他们坐在高位。但最终他成为第一个为信仰流血的使徒。从雷子到殉道者——这是门徒最深的成全。神有时用生命来印证信仰，而他的死没有让教会退缩，反而让信徒更勇敢。', '太4，徒12', '主，西庇太的雅各是第一个为你殉道的使徒。帮助我也有这样的忠心——不是感情用事，而是真实委身，愿意为你付上代价。阿们。', true),
    (213, '腓力', 'Philip the Apostle', '新约时代', '使徒', NULL, '正面', '带人来见耶稣', '伯赛大人，被耶稣第一批呼召，立刻去找拿但业说：我们找到了摩西所写的那一位。在喂饱五千人前被耶稣测试信心，在最后晚餐时说：求主将父显给我们看。', '腓力第一次出现就去找朋友：我们找到了。他的第一反应是分享。在喂五千人前，耶稣问他：我们哪里买饼给这些人吃？腓力算了算：二百两银子的饼也不够。他是务实的计算者，也是真实的寻道者。他问：求主将父显给我们看——这是每个追求者心里最深的渴望。', '约1，约6，约14', '主，腓力找到了你，立刻去找朋友分享。帮助我也有同样的反应——遇见你，就去找人。阿们。', true),
    (214, '巴多罗买', 'Bartholomew', '新约时代', '使徒', NULL, '正面', '没有诡诈的真以色列人', '即拿但业，被耶稣称赞为「真正的以色列人，心里没有诡诈」。起初质疑拿撒勒能出什么好的，被腓力说服来见耶稣后，立刻认定祂是神的儿子。', '耶稣看见他来就说：看哪，这是个真以色列人，他心里没有诡诈。拿但业问：你怎么认识我？耶稣说我看见你在无花果树底下。这一句话足够了。没有诡诈的心，配得上神完全的知道。他被完全知道，因此也完全信任。', '约1', '主，你看见拿但业在无花果树底下。你也看见我一切隐藏的地方。帮助我像他一样，被完全知道，仍然完全信任你。阿们。', true),
    (215, '马太', 'Matthew', '新约时代', '使徒', NULL, '正面', '从税吏到使徒的蜕变', '税吏利未，被耶稣呼召时立刻离开税关跟从，随即摆设大筵席欢迎耶稣，后来写下四福音书之首——马太福音。', '耶稣路过税关，看见他，说：来跟从我。他就起来跟从了。这是圣经最短也最完整的呼召回应。一个被社会鄙视的税吏，被人人嫌弃，却被耶稣选上。他的第一反应是设宴庆祝，请来一群罪人。耶稣来不是召义人，乃是召罪人。马太的故事是最真实的这句话的活注解。', '太9，太10', '主，马太在税关上被你看见、被你呼召。帮助我在我的「税关」上也听见你的声音，立刻起来跟从。阿们。', true),
    (216, '奋锐党的西门', 'Simon the Zealot', '新约时代', '使徒', NULL, '正面', '热心从政治转化为属灵', '热心党人，原本致力于以武力驱逐罗马的政治运动，被耶稣呼召后，将热心完全用于神国。', '他和马太同在十二使徒名单里——一个是罗马帝国的收税人，一个是抵抗罗马的革命者。耶稣偏偏把这两个人放在一起。这是最不可能的和解。神国的奥秘：彼此仇恨的人，因耶稣而成为弟兄。他的热心没有消失，只是对象从政治换成了神国。', '太10，路6', '主，热心党西门的热心被你重新定向。帮助我把我所有的热情交给你，让你来决定它应该指向何处。阿们。', true),
    (217, '达太', 'Thaddaeus', '新约时代', '使徒', NULL, '正面', '无名使徒的忠心', '又名犹大（非加略人），在最后晚餐中问耶稣：主啊，你要将自己显现给我们，不显现给世人是什么缘故？是问出了许多信徒心中的疑惑。', '他只在使徒名单和一个问题里出现。但这个问题不小：为什么你只向我们显现？耶稣的回答是：爱我的人，我父也必爱他，我们要到他那里去，与他同住。达太代表了每一个不出名、不被历史记载却真实跟随的门徒。神的国不只需要彼得和保罗，也需要达太。', '约14，路6', '主，达太问出了我们很多人心里的问题。帮助我有勇气在你面前问真实的疑惑，然后安静听你的回答。阿们。', true),
    (218, '马提亚', 'Matthias', '新约时代', '使徒', NULL, '正面', '被神拣选填补缺口', '在五旬节前被选为替代犹大的第十二使徒，从耶稣受洗到复活一直跟随，只因神拣选而成为使徒。', '彼得说：必须从那些常与我们作伴的人中立一位。马提亚就是这种人——一直跟随，从来没有在聚光灯下，没有自荐，只是在那里。然后神的拣选落在他身上。他的故事告诉我们：忠心的跟随本身就是资格。不需要出名，只需要在场。', '徒1', '主，马提亚一直在场，然后神的拣选落在他身上。帮助我不追求聚光灯，只求忠心在场。你的拣选在你手里，我只需要跟随。阿们。', true),
    (205, '撒母耳', 'Samuel', '士师时代', '先知', NULL, '正面', '从小听见神声音到终生忠心事奉', '由哈拿许愿归还给神的孩子，在圣殿由以利抚养，幼年便听见神的呼唤，成为以色列最后一位士师和最伟大的先知之一。', '神三次呼唤撒母耳，他以为是以利在叫他，三次去问以利。以利终于明白是神在说话，教他说：请说，你仆人敬听。然后神的话来到了。人生最重要的装备，是学会分辨神的声音。他终生保持了这种聆听。撒上12:3：我在这里，你们可以在耶和华和祂的受膏者面前控告我。这是终生清白的宣告。', '撒上1-25', '主，撒母耳从幼年就学会说：请说，你仆人敬听。帮助我今天也以这样的姿态来到你面前，安静地等候你的声音。阿们。', true),
    (219, '亚比央', 'Abijam', '王国时代', '君王', '南国犹大', '警戒', '神的恩典超越父辈的失败', '罗波安之子，犹大第二王，效法父亲的罪，心不专一，但神因大卫之故仍保守其位。', '神在亚比央软弱的生命中仍然施恩，因祂对大卫的应许不改变。恩典不依靠我们的表现，而依靠神的信实。', '王上15:1-8', '主，亚比央的故事提醒我你的恩典不依赖我的完美。感谢你因耶稣的缘故对我施恩。阿们。', true),
    (220, '约兰', 'Jehoram', '王国时代', '君王', '南国犹大', '警戒', '婚姻关系影响属灵方向', '犹大王，约沙法之子，娶亚哈之女为妻，行以色列王的道，杀害兄弟，带领犹大悖逆神。', '他娶了错误的配偶，走上了错误的路。属灵关系对我们的信仰方向影响极深。', '代下21', '主，帮助我选择能使我更靠近你的亲密关系，也帮助我成为带人归向你的人。阿们。', true),
    (221, '亚哈谢', 'Ahaziah', '王国时代', '君王', '南国犹大', '警戒', '错误的辅导者带来毁灭', '犹大王，受母亚他利雅及亚哈家族影响行恶，与以色列王约兰联合出征，被耶户所杀。', '他的母亲和顾问把他带向毁灭。我们无法独自成长，选择谁做我们的属灵导师至关重要。', '代下22:1-9', '主，帮助我谨慎选择属灵导师，也求你保护我免受错误影响的伤害。阿们。', true),
    (222, '亚他利雅', 'Athaliah', '王国时代', '君王', '南国犹大', '警戒', '权力欲摧毁最亲的人', '亚哈之女，以色列历史上唯一的女王，杀尽王孙欲独揽大权，统治六年，后被推翻处死。', '她为了权力杀尽自己的孙子。权力欲到顶点可以摧毁一切人性和关系。', '代下22:10-23:21', '主，保护我的心免于权力欲的腐蚀。帮助我看清：有些代价永远不值得付。阿们。', true),
    (223, '亚们', 'Amon', '王国时代', '君王', '南国犹大', '警戒', '谦卑与骄傲带来不同结局', '玛拿西之子，犹大王，不像父亲玛拿西晚年谦卑悔改，反而变本加厉行恶，仅两年即被臣仆所杀。', '父亲玛拿西悔改了，但儿子亚们没有学会父亲悔改后的谦卑，只承袭了父亲的罪。悔改的榜样需要被接受，才能发挥作用。', '代下33:21-25', '主，帮助我不只看见前辈的失败，也真实接受他们悔改的功课，走在谦卑的道路上。阿们。', true),
    (224, '约哈斯', 'Jehoahaz', '王国时代', '君王', '南国犹大', '警戒', '短暂的机遇需要真实的委身', '约西亚之子，仅在位三个月即被法老尼哥废黜押往埃及，行耶和华眼中看为恶的事。', '约西亚死后，儿子没有承接父亲的精神。属灵遗产需要下一代主动承接，才能延续。', '王下23:31-34', '主，帮助我珍惜从敬虔前辈那里承接的属灵遗产，不要轻易丢弃。阿们。', true),
    (225, '约雅敬', 'Jehoiakim', '王国时代', '君王', '南国犹大', '警戒', '抵挡神的话语终必失败', '犹大王，烧毁耶利米的卷轴，拒绝神的话，最终在巴比伦第一次入侵时臣服，是敌挡神话语的警戒。', '他拿刀割断耶利米的书卷，逐段扔进火中。这是人类史上最傲慢的反应之一——把神的话一节一节地烧掉。结果呢？神的话一字不差地应验了。', '耶36', '主，帮助我以约雅敬为鉴，以谦卑开放的心来到你的话语面前，不抵挡你对我说的话。阿们。', true),
    (226, '约雅斤', 'Jehoiachin', '王国时代', '君王', '南国犹大', '混合', '神在被掳中仍有恩典', '犹大末代王之一，在位仅三个月即被掳往巴比伦，晚年在巴比伦被释放并蒙厚待，是恩典超越审判的微小信号。', '他在巴比伦被囚三十七年，却在晚年被释放，受到巴比伦王的厚待。即使在最漫长的审判中，神仍然保留了一线恩典和盼望。', '王下24:8-17；王下25:27-30', '主，约雅斤三十七年后得到恩待。帮助我相信即使在漫长的等待和审判中，你仍然记念我，仍有恩典为我保留。阿们。', true),
    (227, '西底家', 'Zedekiah', '王国时代', '君王', '南国犹大', '警戒', '软弱的妥协比强硬的拒绝更危险', '犹大最后一位王，多次私下询问耶利米却不敢公开顺从，在恐惧中妥协，目睹儿子被杀后双目被剜，南国灭亡。', '他私下去见耶利米，问：有没有神的话？他知道神的话，却不敢照着行。软弱的知道而不行，有时比强硬的拒绝更悲剧。他的眼睛看见了儿子被杀，然后永远失明——他最后的记忆是最惨的记忆。', '耶37-39', '主，保护我不要成为西底家——知道你的话却因惧怕人而不敢行。给我勇气，在知道你旨意的地方公开顺从。阿们。', true),
    (228, '拿答', 'Nadab', '王国时代', '君王', '北国以色列', '警戒', '罪的代价从不迟到', '北国第二王，耶罗波安之子，继续父亲的罪，在位仅两年即被巴沙谋杀，耶罗波安家族绝灭。', '他继承了父亲的罪，也继承了父亲的审判。罪的代价可能延迟，但从不取消。', '王上15:25-31', '主，帮助我不要继承家族的罪性模式，而是成为那个打破循环、选择归向你的人。阿们。', true),
    (229, '暗利', 'Omri', '王国时代', '君王', '北国以色列', '警戒', '政治成就掩盖不了属灵的失败', '北国以色列强盛王，建撒玛利亚城，在政治军事上极有建树，但在属灵上行比前人更恶的事。', '他在历史上是强大的王，在神的眼中却是「行恶过于以前的列王」。世人的成功排行榜和神的评价可以完全相反。', '王上16:21-28', '主，帮助我不以世界的标准来衡量成功，而以你的眼光来看我生命的价值和方向。阿们。', true),
    (230, '耶户', 'Jehu', '王国时代', '君王', '北国以色列', '混合', '热心执行神的命令却心不专一', '被神膏立推翻亚哈家族，彻底铲除巴力崇拜，但自己仍走在耶罗波安的罪中，心不专一归向神。', '神称赞他执行了神的命令，却也说他心不专一。热心于神的工作，不等于心完全归向神。行动的忠心和内心的忠心需要同时检验。', '王下9-10', '主，不要让我成为耶户——热心于你的工作，却心不完全归向你。帮助我从心里爱你，而不只是完成宗教任务。阿们。', true),
    (231, '约哈斯（北）', 'Jehoahaz of Israel', '王国时代', '君王', '北国以色列', '混合', '苦难中求告神是软化的开始', '北国王耶户之子，在位期间因亚兰人逼迫而求告神，神垂听并施拯救，但他最终仍未离弃偶像。', '在苦难最深时他「恳求耶和华」，神就听了他的祷告。苦难可以软化最刚硬的心，促使人转向神——即使那个转向还不彻底。', '王下13:1-9', '主，感谢你在我不完美的求告中仍然垂听。帮助我不只在苦难中求你，在得救后也不回到旧路。阿们。', true),
    (232, '约阿施（北）', 'Joash of Israel', '王国时代', '君王', '北国以色列', '混合', '信心的力度决定得胜的幅度', '北国王，去探望垂死的先知以利沙，信心不足只射了三箭，以利沙指出他原可完全得胜，却因信心不足只得部分胜利。', '以利沙让他射箭，他只射了三次就停下来。以利沙说：你应当射五六次，那时你就能完全胜过亚兰人。你的得胜幅度与你信心的力度有直接关联。', '王下13:10-25', '主，不要让我成为只射三箭的人。在你面前帮助我不保留，全力信靠，让信心的力度与你愿意给的祝福相称。阿们。', true),
    (233, '法老', 'Pharaoh', '出埃及时代', '君王', '外邦君王', '警戒', '刚硬的心使人错过悔改的机会', '埃及王，十次拒绝神借摩西发出的警告，每次灾难过后就心硬如石，最终在红海中覆灭，是人类历史上最典型的刚硬与悖逆案例。', '每一次灾难之后，神给他机会悔改，他却一次次心硬。圣经说神刚硬他的心——这不是神强迫他犯罪，而是神让他完全表现出他本来就有的刚硬。他不是被迫走向毁灭，而是一步步选择拒绝神。', '出5-14', '主，保护我的心不要法老式地刚硬。当你用任何方式对我说话时，帮助我真实地听见，真实地回应，不要只等苦难过去就忘记你的声音。阿们。', true),
    (235, '约押', 'Joab', '王国时代', '其他', NULL, '警戒', '才能与忠诚不能掩盖以私利杀人的罪', '大卫最得力的元帅，征战无数立功卓著，却三次以私利擅自杀死无辜（押尼珥、押沙龙、亚玛撒），最终被所罗门依大卫遗命处死。', '他忠于大卫的王权，却不忠于大卫的神。他可以打赢所有的战争，却输掉了自己灵魂的战争。才能和功绩不能为以私利伤人开脱。他的悲剧在于：他知道大卫的心意，却一次次选择自己的判断凌驾于神的命令之上。', '撒下2-20，王上2', '主，约押的一生提醒我：再大的才能和贡献，都不能成为以私意行事的理由。帮助我在有能力的地方更加顺服，而不是更加自主。阿们。', true),
    (248, '迦得', 'Gad', '王国时代', '先知', NULL, '正面', '忠心传递神的管教信息是先知最重要的职责', '大卫的先见，忠心将神因大卫数点人口的审判信息带给大卫，并在大卫选择刑罚时陪伴他度过最艰难的时刻，后协助大卫建立圣殿礼仪。', '神给大卫三个选项，迦得忠心带去信息，不加任何粉饰。先知的责任不是让人舒服，而是让人听见神的声音。最艰难的信息往往需要最忠心的使者。', '撒下24:11-14', '主，迦得忠心带去难听的信息，却不离开大卫。帮助我在说真话的时候，也有迦得式的陪伴和忠心。阿们。', true),
    (249, '亚希雅', 'Ahijah', '王国时代', '先知', NULL, '正面', '神的话语必然成就，先知只是忠心的传声筒', '示罗的先知，将外袍撕成十二片预言王国分裂，将十片给耶罗波安；晚年双目失明，仍凭神的话语准确预言耶罗波安家族的覆灭。', '他年轻时撕袍预言，老年双目失明却依然准确。眼睛看不见，但神的话语在他心里清清楚楚。真正的先知靠的不是洞察力，而是神的启示。', '王上11:29-39，王上14:1-18', '主，亚希雅在最不方便的时候仍然忠心传达你的话。帮助我无论处境如何，都忠心地把你的话带给需要的人。阿们。', true),
    (250, '示玛雅', 'Shemaiah', '王国时代', '先知', NULL, '正面', '及时的神的话能阻止不必要的流血', '神人，在王国分裂后阻止罗波安攻打北国，后在示撒入侵时传神话语，使南国君臣悔改，得以从全灭中保全。', '一句话让十八万军队放下武器。神借先知说话，不是为了表演权威，而是为了拯救生命。他在最紧张的政治时刻带去神的话，两次都让人听从了——这是极其罕见的。', '王上12:22-24，代下12:5-8', '主，示玛雅一句话止住了战争。帮助我在冲突中敏锐听见你的声音，也有勇气把你的话说出来，相信你的话能改变局面。阿们。', true),
    (251, '米该雅', 'Micaiah', '王国时代', '先知', NULL, '正面', '只说神所说的话，即使四百人都说相反', '以色列先知，面对四百个一致说好话的假先知，独自坚持传达神真实的信息——亚哈必败，最终被投入监狱，但预言应验。', '四百个先知说：去吧，必然得胜。只有他一个人站出来说：不。他知道这意味着什么。被打了一巴掌，被关进监狱，但他说：我几时平平安安回来，耶和华就没有藉我说话。这是先知的骨气。', '王上22:1-28', '主，米该雅一个人对四百个。帮助我在众人都说好的时候，仍然敢于说出你真实的话，把结果交给你。阿们。', true),
    (252, '俄底', 'Oded', '王国时代', '先知', NULL, '正面', '先知的话也能阻止骄胜者的残暴', '撒玛利亚先知，在北国以色列大胜南国并掠夺二十万人时，单人出面阻止，要求释放俘虏，被领袖们听从，俘虏被妥善遣返——圣经中最感人的人道主义时刻之一。', '他出去迎接凯旋的军队，对他们说：你们已经胜了，但神不是要你们灭绝弟兄。一个人，没有军队，没有政治地位，只有神的话——四个首领听从了他，将俘虏全部放回。有时神的话能在一瞬间改变人的心。', '代下28:9-15', '主，俄底一人阻止了二十万人的苦难。帮助我在有机会阻止伤害的时候，有俄底的勇气站出来说话，相信你的话能软化人心。阿们。', true),
    (274, '耶稣基督', 'Jesus Christ', '新约时代', '主&救主', NULL, '正面', '祂是圣经六十六卷的核心与终点——旧约所有人物都是祂的影子，新约揭示祂的真身。祂道成肉身，完全认同人的软弱；在客西马尼俯伏祷告，完全顺服父的旨意；在十字架上承担全人类的罪；在复活中宣告死亡已被征服。祂不只是最好的榜样，祂是我们得以效法任何榜样的力量来源。', '耶稣基督，神的永恒之子，在创世之先已存在（约1:1），在时间的中心成为肉身（约1:14），藉马利亚生于伯利恒（路2:7），在拿撒勒成长（路2:51-52），约三十岁开始传道，在加利利、撒玛利亚和犹大宣扬天国福音、医治病人、赶鬼、使死人复活。祂召聚十二门徒，以比喻和登山宝训教导神国的生活方式。在逾越节前夕，祂设立圣餐（太26:26-28），在客西马尼园流血汗祷告（路22:44），被犹大出卖，经彼拉多审判，在各各他十字架上受死（约19:30），第三天复活（路24:6），四十天后升天（徒1:9），将来必再来审判活人死人（启22:20）。祂的生命囊括了所有人类处境：贫穷、拒绝、孤独、误解、背叛、苦难、死亡——祂都亲身经历，因此祂是完全能体恤我们的大祭司（来4:15-16）。', '圣经每一位人物的功课，都在祂身上找到完全的原型与成就：\n亚当失去的，祂作为末后的亚当来恢复（林前15:45）；\n挪亚造方舟拯救人，祂以十字架拯救全人类；\n亚伯拉罕愿意献以撒，祂是那真正被献的独生子（约3:16）；\n约瑟被兄弟出卖却成为救恩的管道，祂被门徒出卖却成为世界的救主；\n摩西是中保和代求者，祂是唯一的中保（提前2:5）；\n大卫是按神心意的牧羊王，祂是好牧人（约10:11），是大卫更伟大的子孙（太22:42-45）；\n以利亚在旷野中疲惫，天使来喂养，祂在旷野四十天禁食受试探，却胜过了每一个试探；\n约伯在苦难中质问神，祂在十字架上喊出「我的神，我的神，为何离弃我」（诗22:1，太27:46）——这是祂真实承担了人类被遗弃感的记号；\n路得说「你往哪里去，我也往那里去」，祂道成肉身进入人类的处境，比路得更彻底地委身；\n约拿在鱼腹三天，预表祂在地里三天（太12:40）；\n以赛亚53章所描绘的受苦仆人，就是祂——「他为我们的过犯受害，为我们的罪孽压伤」。祂不是圣经众人物之一，祂是所有人物指向的那一位。', '太1-28，可1-16，路1-24，约1-21，腓2:5-11，来1-13，启1:8', '主耶稣，你是圣经的核心，是一切人物的终点，是我们所有功课的完全示范。感谢你道成肉身，进入我们最真实的处境；感谢你在客西马尼的祷告，告诉我们顺服的样式；感谢你在十字架上说『父啊，赦免他们』，让我们知道爱可以在最深的痛苦中仍然给出；感谢你复活，让我们知道最黑暗的死亡不是终点。帮助我不只是仰慕你，更是住在你里面，让你的生命从我里面流出，而不是我努力模仿你在外面。你是主，你是救主，也是我今天最真实的同行者。阿们。', true),
    (271, '亚萨', 'Asaph', '王国时代', '其他', NULL, '正面', '在最深的属灵困惑中诚实地向神呼求，是真正的信心', '大卫时代的乐师和诗人，被委任管理会幕的诗歌敬拜，创作了12篇诗篇。诗篇73篇是他在信仰最大危机时的诚实呼求：为何恶人亨通？他几乎跌倒，直到进入圣所才得到答案。', '诗73说：我的脚几乎滑跌。他险些因为看见恶人亨通而失去信仰。然后他说：及至我进入神的圣所，才明白他们的结局。不是神给他讲道，而是他进入了神的同在。属灵困惑的出路不是更多答案，而是更真实的同在。', '诗73-83', '主，亚萨几乎跌倒，却进入圣所找到了答案。帮助我在最深的属灵困惑中，不逃避也不装作没问题，而是诚实地来到你面前，在你的同在中得到出路。阿们。', true),
    (272, '可拉的后裔', 'Sons of Korah', '王国时代', '其他', NULL, '正面', '从家族的审判中被救出来，成为赞美的传递者', '可拉在旷野因叛乱被地吞没，但他的儿子们没有与他一同死亡（民26:11），后来成为圣殿的乐师和诗人，写下11篇诗篇，包括诗篇84「我灵渴慕你的殿宇」和诗篇46「神是我们的避难所」。', '他们的父亲因叛逆被地活吞，他们却没有死——民数记特意记载这一点。从审判的边缘被救出来的人，写出了最深刻的渴慕诗。诗84说：我灵渴慕，甚至昏乏。这不是平静日子里的赞美，这是从深处升起的渴慕。经历过险境的人，赞美有不同的重量。', '诗42-49，诗84-88', '主，可拉的后裔从父亲的审判中被救出来，却没有带着苦毒，而是写出了最深的渴慕。帮助我也在家族或过去的阴影中，选择渴慕你而不是承接仇恨。阿们。', true),
    (273, '犹大（耶稣兄弟）', 'Jude brother of Jesus', '新约时代', '其他', NULL, '正面', '从不信到为信仰力争，恩典改变了他对哥哥的看法', '耶稣的兄弟，早期不信耶稣（约7:5），复活后成为信徒（徒1:14），后写下犹大书，力劝信徒「为从前一次交付圣徒的真道竭力争辩」，是从家人不信到护教者的转化典范。', '他与耶稣一起长大，却不信他是弥赛亚。然后复活改变了一切。写犹大书的他说：我原本想写一般的得救教导，但我不得不写这封紧急信——有人正在曲解恩典。从怀疑自己哥哥，到为哥哥的真道竭力争辩，这个转变只有复活才能解释。', '犹大书1，约7:5，徒1:14', '主，犹大曾经不信自己的哥哥就是基督。但复活改变了他，使他成为为真道力争的人。帮助我也在信仰上不只是接受，更是有胆量在需要的时候为真道站立。阿们。', true),
    (259, '流便（雅各长子）', 'Reuben', '族长时代', '其他', NULL, '混合', '长子的地位因一次冲动而永久失去', '雅各长子，有长子名分，却因与父亲的妾同寝失去长子权；卖约瑟时曾想营救却未能拦截；在约瑟面前第一个说出良心的声音。是冲动毁掉长子权、却在关键时刻仍有良知的复杂人物。', '他有名分，却没有品格来撑起名分。一次冲动的犯罪永久改变了他的命运。但他也是在约瑟被卖后第一个说「我们现在受罚」的人——良心还在，只是太迟了。有时最可悲的不是没有良心，而是良心虽在却行动太晚。', '创35:22，创37，创42-43，创49:3-4', '主，流便有长子名分，却因一次冲动失去了一切。帮助我在冲动面前停下来，相信自律比事后悔恨更有价值。阿们。', true),
    (260, '西缅与利未（雅各之子）', 'Simeon and Levi', '族长时代', '其他', NULL, '警戒', '愤怒的报复带来的伤害超出你的预期', '雅各第二、三子，因妹妹底拿被玷污，用欺骗手段使示剑人行割礼，趁其虚弱时屠城，雅各因此责备他们；临终祝福中被宣告将在以色列中被分散。', '他们的愤怒有合理的根源——妹妹被玷污是真实的伤害。但他们的报复方式——欺骗、屠城、掳掠——已经超出了公义，进入了残暴。雅各说：我因你们臭了，使我在这地的居民中令人厌恶。愤怒是真实的，但愤怒不能成为超越界限的借口。', '创34，创49:5-7', '主，西缅和利未的愤怒有道理，但他们的行动失控了。帮助我在最愤怒的时刻不让愤怒替我做决定，将公义交在你手中。阿们。', true),
    (261, '犹大（雅各之子）', 'Judah son of Jacob', '族长时代', '其他', NULL, '混合', '从卖兄弟到甘愿代替弟弟——这是真实的成长', '雅各第四子，建议卖约瑟；中年与他玛之事暴露道德软弱，却在他玛说出真相后承认「她比我更公义」；晚年在约瑟面前甘愿以自己代替便雅悯。是圣经中最真实的悔改成长案例之一，弥赛亚从他而出。', '他卖了约瑟，多年后却站在约瑟面前说：让我替代便雅悯留下，不要让父亲再受苦。这不是同一个人——或者说，这是经过真实成长的同一个人。中间经历了他玛事件的羞辱和认错。从出卖到代替，是真实的悔改轨迹。', '创37，创38，创44，创49:8-12', '主，犹大从出卖弟弟到甘愿代替。帮助我也有这样真实的成长轨迹——不只是感到懊悔，而是在关键时刻用行动证明我已经改变了。阿们。', true),
    (262, '但（雅各之子）', 'Dan son of Jacob', '族长时代', '其他', NULL, '混合', '支派的潜力需要对神的忠心才能实现', '雅各第五子（辟拉所生），雅各预言他将审判百姓如以色列一个支派；但但支派后来成为第一个引进偶像的支派，在士师记中迁移并设立偶像敬拜，最终从启示录的十二支派中被省略。', '雅各为他祷告：耶和华啊，我等候你的救恩！这是一声叹息——仿佛雅各已经预见这支派将会走偏。潜力最大的名分，有时也伴随最深的试探。但支派的故事提醒我们：神赐的潜力需要顺服才能实现，否则就变成一个注脚。', '创49:16-18，士18', '主，但支派有极大的潜力，却走向了偶像。帮助我不辜负你赐给我的潜力，将每一份才能和呼召都归回给你。阿们。', true),
    (263, '拿弗他利（雅各之子）', 'Naphtali son of Jacob', '族长时代', '其他', NULL, '正面', '轻捷自由地传递美好的话语是神的恩赐', '雅各第六子（辟拉所生），雅各预言他如放开的母鹿，传美好的消息；他的支派地业在加利利，以赛亚预言那里的人将看见大光，耶稣在此开始传道，应验了这地业的属灵意义。', '他本人的故事简短，但他的支派地业成为耶稣传道的起点。有时一个人的呼召要经过几百年才能完全显现。雅各说：传美好的消息——这句预言最终在加利利的耶稣身上完全实现了。', '创49:21，赛9:1-2，太4:13-16', '主，拿弗他利的地业预言了几百年后的光。帮助我在我所在的地方，忠心地传递你的美好消息，相信你在我的位置上早已有你的计划。阿们。', true),
    (264, '迦得（雅各之子）', 'Gad son of Jacob', '族长时代', '其他', NULL, '正面', '在压迫中仍然得胜是神子民的标志', '雅各第七子（悉帕所生），雅各预言他将受敌军攻击，但他终必得胜；他支派的地业在约旦河东，边境地区，经历了真实的争战考验。', '雅各只用了一句话描述他：必有军旅攻击他，他却要攻击他们的脚跟。这是边境子民的命运——不断受攻击，但最终得胜。有时神的应许不是「你不会受攻击」，而是「你虽受攻击，但终必得胜」。', '创49:19', '主，迦得的应许不是平静，而是得胜。帮助我在被攻击的时刻，相信你的话：终必得胜。不是因为我强，而是因为你在。阿们。', true),
    (265, '亚设（雅各之子）', 'Asher son of Jacob', '族长时代', '其他', NULL, '正面', '神的祝福使人有余裕去祝福别人', '雅各第八子（悉帕所生），雅各预言他出产肥美的食物，供给君王；他的地业在迦南西北的沿海肥沃之地；新约中的女先知亚拿出自亚设支派，在圣殿见到婴儿耶稣并颂赞神。', '雅各说：亚设的出产必是肥美的食物，必奉给君王。从丰富中给出，是祝福的传递。几百年后，亚设支派出了一位八十四岁的女先知亚拿，她在圣殿里等候弥赛亚——从肉体的丰盛到属灵的期盼，支派的祝福在她身上以另一种方式实现了。', '创49:20，路2:36-38', '主，亚设的祝福从肥美的出产到属灵的等候。帮助我不只享用你给我的丰盛，更要成为别人祝福的来源，并像亚拿一样持续地等候你。阿们。', true),
    (266, '以萨迦（雅各之子）', 'Issachar son of Jacob', '族长时代', '其他', NULL, '混合', '安稳的地业需要警惕不要换成安逸的顺服', '雅各第九子（利亚所生），雅各预言他如驴伏卧在羊圈之中，他看地业甚好，就弯肩担担，成了服苦的人；但以萨迦支派后来出了明白时势知道以色列当做何事的二百个领袖，是判断力的代表。', '雅各的预言有两面：一面是他看地业甚好，甘心服苦；另一面是圣经后来称赞以萨迦人「明白时势」。安稳的人若保持清醒，可以成为最有智慧的领袖；若只顾享受安稳，就变成甘心服苦的驴。', '创49:14-15，代上12:32', '主，以萨迦有安稳的地业，却要小心不要成为只顾安稳的驴。帮助我在稳定中保持清醒，成为一个明白时势、知道当做何事的人。阿们。', true),
    (267, '西布伦（雅各之子）', 'Zebulun son of Jacob', '族长时代', '其他', NULL, '正面', '处于十字路口的地位是神放置的宣教机会', '雅各第十子（利亚所生），雅各预言他必住在近海之处，成为船只的海口；他的地业在迦南西北靠近地中海，是商业和文化的交汇处；其地业也在加利利，与以赛亚的弥赛亚预言相关。', '十字路口的位置意味着你会遇见各种各样的人。雅各说他必住在近海之处，成为船只的海口——这是对外开放的象征。申命记说他们将在山上祭祀，邀请万族来。处于边界的人，若能忠心，就是最自然的宣教士。', '创49:13，申33:18-19，赛9:1-2', '主，西布伦在十字路口的位置不是偶然。帮助我在我所在的交汇处，成为把人引向你的桥梁，而不是被各种文化淹没。阿们。', true),
    (268, '便雅悯（雅各之子）', 'Benjamin son of Jacob', '族长时代', '其他', NULL, '混合', '最幼小的反而常常承载最重的恩典', '雅各最小的儿子，母亲拉结因难产去世；在约瑟故事中成为核心筹码，犹大甘愿代替他留下；雅各称他为撕掠的狼；保罗以出自便雅悯支派为荣。', '他是最幼小的，生来就带着母亲死亡的阴影。雅各为他恳切地护卫。兄弟们把他当筹码，犹大甘愿替他受苦。然而这支派出了以色列第一位王扫罗，和新约最伟大的使徒保罗。最边缘的反而常常成为神历史的转折点。', '创35:16-20，创42-45，创49:27，腓3:5', '主，便雅悯是最幼小的，却承载了极大的恩典。帮助我不因自己看起来最微小而轻看神在我身上的计划。阿们。', true),
    (269, '玛拿西（约瑟长子）', 'Manasseh son of Joseph', '族长时代', '其他', NULL, '混合', '神的拣选不按人的长幼次序', '约瑟的长子，在雅各临终交叉双手祝福时，右手放在弟弟以法莲头上而非长子玛拿西头上，是神不按人预期次序拣选的又一例证。', '约瑟纠正父亲：不是这样，父亲！这是长子。雅各说：我知道，我知道。神的拣选不按我们的预期。玛拿西不是被遗弃的，只是位次不同。神有时选择次子超过长子，不是因为长子不重要，而是为了彰显祂的主权。', '创48:8-20', '主，玛拿西是长子，却不是被拣选放在首位的那个。帮助我接受你的次序而非坚持自己的期待，相信你的安排比我的预期更好。阿们。', true),
    (270, '以法莲（约瑟次子）', 'Ephraim son of Joseph', '族长时代', '其他', NULL, '混合', '被神出乎意外地拣选，要以谦卑回应', '约瑟的次子，雅各交叉双手将右手放在他头上，赐予更大的祝福；他的支派成为北国以色列的核心，甚至「以法莲」成为北国的代名词；但先知何西阿和以赛亚多次警告以法莲的骄傲和背道。', '他是次子却蒙更大的祝福——这是纯粹的恩典，没有任何功绩。问题在于，蒙恩最多的人有时也是最骄傲的。以法莲支派后来自以为是，高傲地认为别人都应该效忠他们。被拣选是恩典，以被拣选为傲是堕落的开始。', '创48:8-20，创49:22-26，何5-14', '主，以法莲蒙了最大的祝福，却走向了骄傲。帮助我将你赐给我的一切恩典都归荣耀给你，而不是让恩典成为骄傲的燃料。阿们。', true),
    (253, '罗得', 'Lot', '族长时代', '其他', NULL, '混合', '眼光短浅的选择带来长远的代价', '亚伯拉罕的侄子，与亚伯拉罕分开时用眼目选择了肥沃但罪恶的所多玛平原，最终在城毁前蒙天使搭救，却失去妻子和一切财产，是以眼目的情欲做选择的警戒案例。', '他举目看，看见约旦河全平原都有水，就选了那里——他用眼睛做了选择。那里肥沃，那里繁华，那里最好。他没有问神，没有寻求智慧，只是看见了。多年后他在那里失去了妻子，失去了一切。眼目的选择不等于智慧的选择。', '创13，创19', '主，罗得用眼目选择了所多玛，我也常常这样。帮助我在重要的抉择前先来到你面前，用你的眼光而不是眼目的欲望来判断方向。阿们。', true),
    (254, '罗得的妻子', 'Lot''s Wife', '族长时代', '女性', NULL, '警戒', '回头看是对神命令最致命的不顺服', '在逃离所多玛时被天使明确命令不许回头，却在逃跑途中回头看，立刻变成盐柱。耶稣自己引用她作为警戒：你们要回想罗得的妻子。', '命令只有一个：不要回头看。她回头了。圣经没有解释为什么——是留恋？是好奇？是不舍？无论是什么，那一回头终结了一切。神的命令不需要理由，只需要顺服。耶稣说：你们要回想罗得的妻子——这句话跨越了几千年，仍然在问我们：你的心在哪里？', '创19:17-26', '主，罗得的妻子一回头就失去了一切。帮助我在你说不要回头的地方，有彻底告别旧生活的勇气，不只是身体离开，更是心完全转向前方。阿们。', true),
    (255, '罗得的女儿们', 'Lot''s Daughters', '族长时代', '女性', NULL, '警戒', '在绝境中用错误的手段解决问题带来长远的祸患', '逃出所多玛后，两个女儿在绝望中用诡计使父亲喝醉并与他同寝，分别生下摩押人和亚扪人的祖先，是在极端处境中以不法手段解决问题的悲剧。', '她们从最道德败坏的城市长大，所多玛的方式已经成为她们的思维框架。面对绝境，她们想出了所多玛式的解决方案。她们的问题是真实的——家族似乎要断绝——但她们的方式带来了几千年的祸患。用错误的方式解决真实的问题，是罪最常见的入口。', '创19:30-38', '主，罗得的女儿在绝境中用了错误的方式。帮助我在最绝望的处境中，仍然相信你有合乎你旨意的出路，而不是自己设计捷径。阿们。', true),
    (256, '俄珥巴', 'Orpah', '士师时代', '女性', NULL, '混合', '理性的选择与信心的选择走向不同的结局', '路得的姑嫂，摩押女子，在拿俄米要她们回娘家时，流泪亲吻婆婆后回到本族，与路得形成鲜明对比。她的选择理性上无可指责，却与神的历史轨迹分道扬镳。', '她也哭了，她也爱拿俄米。但她回去了。这个选择没有对错——拿俄米自己让她们回去。俄珥巴做了一个理性的、安全的、合情合理的选择。路得做了一个疯狂的、没有保障的、超越理性的选择。两条路就此分开，历史只记住了路得。有时信心的选择比理性的选择更有意义。', '路得记1:4-15', '主，俄珥巴的选择理性无误，却与你的计划擦肩而过。帮助我在人生关键的十字路口，不只用理性计算，而是寻求你的心意，有路得式的委身勇气。阿们。', true),
    (257, '米迦（以法莲人）', 'Micah of Ephraim', '士师时代', '其他', NULL, '警戒', '用自己的方式敬拜神，等于拜自己', '以法莲山地的人，私自铸造神像设立家庙，雇用一个利未人作私家祭司，以为这样就得到神的祝福；后来神像被但支派抢走，连祭司也被带走，一切归于虚空。', '他说：现在我知道耶和华必赐福给我，因我有这利未人作祭司。他为自己设计了一套敬拜系统，用自己认为对的方式来敬拜神，却从未问过神要什么。结果神像被抢走了，祭司也走了，一切都消失了。用自己的方式敬拜神，不是在敬拜神，而是在敬拜一个自己设计的神。', '士17-18', '主，米迦用自己的方式敬拜，以为就得到了你。帮助我不把信仰变成自己的宗教系统，而是真实地寻求你、顺从你所要求的敬拜方式。阿们。', true),
    (258, '利未人与他的妾（士师记）', 'Levite and Concubine', '士师时代', '其他', NULL, '警戒', '道德沦丧的社会从每一个人的软弱开始', '士师记最黑暗的事件：一个利未人的妾逃回娘家，他追回后途经基比亚，当夜暴民要求施暴，他将妾推出门外，妾被凌虐至死。他肢解妾的尸体发信号，引发以色列内战几乎灭绝便雅悯支派。是士师记「各人任意而行」的最惨烈注脚。', '那一夜，他把妾推出门外——圣经说他推了出去。他保护了自己，牺牲了她。他之后将尸体肢解，以愤怒之名发动战争，却从未为她的死承担责任。整个事件没有一个人真正以神的标准行事。士师记在最黑暗的故事结尾说：那时以色列中没有王，各人任意而行。', '士19-21', '主，士师记末尾的黑暗提醒我：没有你的标准，人可以堕落到多深的地步。帮助我在这个时代持守你的公义和怜悯，成为黑暗中有光的人。阿们。', true),
    (241, '以笏', 'Ehud', '士师时代', '其他', NULL, '正面', '神使用出人意料的人完成看似不可能的任务', '以色列第二位士师，左撇子，用精心策划的行动刺杀了压迫以色列十八年的摩押王伊矶伦，带领以色列得安息八十年。', '他是左撇子——那个时代这被视为缺陷，剑却藏在右腿，守卫没有搜查。神不只使用完美的人，祂使用愿意顺服、被认为有缺陷的人。出人意料，正是神工作的风格。', '士3:12-30', '主，以笏提醒我：你不按世界的标准选人。帮助我不因自己的弱点而退缩，相信你能使用真实的我完成你的呼召。阿们。', true),
    (242, '珊迦', 'Shamgar', '士师时代', '其他', NULL, '正面', '用手中现有的工具，在你所在的地方事奉神', '以色列第三位士师，用赶牛的棍子击杀六百非利士人，拯救以色列，是圣经中记载最简短却最有力的士师。', '整段记载只有一节经文。没有背景故事，没有神的异象，没有大军。只有一个人，一根赶牛棍，和六百个敌人——他打赢了。神不等你装备齐全，神使用你手中现有的。', '士3:31', '主，珊迦只有一根棍子，却用它改变了以色列的命运。帮助我不轻看手中所有的，勇敢地在我所在之处为你而行。阿们。', true),
    (243, '陀拉', 'Tola', '士师时代', '其他', NULL, '正面', '安静忠心的治理也是神所记念的服事', '基甸之后的士师，安静治理以色列二十三年，圣经没有记载他的战功或过失，只说他起来拯救以色列。', '他没有大战役，没有戏剧性的神迹，没有失败的教训。只有二十三年的安静忠心。神的记录本里，这二十三年没有被遗忘。有时最伟大的服事是那些没有掌声的持续守护。', '士10:1-2', '主，陀拉二十三年安静守护，你都记念。帮助我不因服事没有掌声而灰心，相信每一个忠心的日子都在你的记录里。阿们。', true),
    (244, '睚珥', 'Jair', '士师时代', '其他', NULL, '混合', '祝福需要管理，权势需要警醒', '治理以色列二十二年的士师，有三十个儿子骑三十匹驴驹，管理三十座城，家族富足显赫，但圣经对其属灵遗产没有明确称赞。', '他的记载充满数字：三十个儿子，三十匹驴，三十座城。这是世界的繁荣，不是属灵的遗产。拥有很多，却未必留下最重要的东西。', '士10:3-5', '主，睚珥有三十个儿子和三十座城，却没有留下属灵的见证。帮助我在神所赐的丰盛中，首先建立属灵的遗产而不只是物质的遗产。阿们。', true),
    (245, '以比赞', 'Ibzan', '士师时代', '其他', NULL, '正面', '在自己的岗位上尽责是神所悦纳的', '伯利恒的士师，治理以色列七年，有三十个儿子和三十个女儿，在百姓中建立家庭网络，平稳度过任期。', '七年，三十个儿子，三十个女儿。他的记载简短，但他在那个动荡的时代提供了稳定。不是每个呼召都需要戏剧性的故事，有时尽职守责就是最大的贡献。', '士12:8-10', '主，以比赞在平凡的岗位上忠心七年。帮助我不轻看平凡的委身，在我的岗位上做一个可靠的人。阿们。', true),
    (246, '以伦', 'Elon', '士师时代', '其他', NULL, '正面', '默默无闻的忠心也是神国的根基', '西布伦人，治理以色列十年，圣经关于他的记载只有两节，没有战功也没有过失，是最静默的士师之一。', '两节经文，十年服事。没有故事，没有名言，没有神迹。只有神知道这十年里他做了什么。有时最忠心的服事留在历史的页边空白处，却写在神的心里。', '士12:11-12', '主，以伦只有两节经文，却有十年忠心。帮助我不因没有掌声而改变方向，学会做一个你看见、你记念的人，即使世界不记得我。阿们。', true),
    (247, '押顿', 'Abdon', '士师时代', '其他', NULL, '混合', '家族的繁荣需要与属灵的根基相连', '比拉顿人，治理以色列八年，有四十个儿子和三十个孙子，全都骑驴驹，家族庞大显赫，圣经没有记载他的属灵遗产。', '四十个儿子，三十个孙子，全骑驴驹。这是一幅家族荣耀的图画，却缺少了神的名字。拥有最多家人的人，需要最认真地思考：我留给他们的是什么遗产？', '士12:13-15', '主，押顿有庞大的家族，却没有留下属灵的见证。帮助我在建造家庭的过程中，始终以属灵遗产为最重要的优先。阿们。', true),
    (237, '以利', 'Eli', '士师时代', '祭司', NULL, '警戒', '溺爱儿子等于放弃神赐的责任', '以色列大祭司，属灵上忠心敬虔，却因纵容两个儿子何弗尼与非尼哈在圣所犯罪，神责备他「尊重儿子过于尊重我」，最终儿子阵亡、约柜被掳、以利自己跌死，家族祭司职分被剥夺。', '神对他说：你为何践踏我的祭祀和供物，尊重儿子过于尊重我？他不是不知道，他只是不管教。知道而不行动，有时比不知道更沉重的罪。他爱儿子，但他的爱没有纠正，只有纵容——这不是爱，是遗弃。', '撒上1-4', '主，以利的悲剧提醒我：爱不是纵容。帮助我在最亲近的关系中，有勇气按神的标准说真话、行真爱，而不是用沉默来讨好人。阿们。', true),
    (238, '亚比亚他', 'Abiathar', '王国时代', '祭司', NULL, '警戒', '忠心多年却在最后一步站错队', '大卫患难时期的忠心祭司，唯一从挪伯祭司大屠杀中逃脱者，陪伴大卫多年患难与共，却在晚年支持亚多尼雅争位而非所罗门，最终被所罗门废黜，印证了神对以利家族的预言。', '他在大卫最危险的时期选择了大卫，付出了一切。但他最后一次选择选错了方向。多年的忠心不能自动保证最后的选择是对的。每一次选择都是新的选择，没有老本可吃。', '撒上22-23，王上2', '主，亚比亚他提醒我：没有任何过去的忠心可以让我在今天不需要认真选择。帮助我每一天都重新选择你，不靠老本，不凭惯性。阿们。', true),
    (239, '撒督', 'Zadok', '王国时代', '祭司', NULL, '正面', '在政治动荡中坚守对神所立君王的忠诚', '大卫和所罗门时期的大祭司，押沙龙叛乱时选择与大卫同行，约柜被带出后遵命送回耶路撒冷；所罗门争位时坚定支持神所拣选的所罗门，最终受重用成为所罗门朝的大祭司。', '押沙龙叛乱时，他抬着约柜跟随大卫出城。大卫对他说：你把神的约柜抬回城去……你是先见，就安然回城去吧。他顺服了，带着约柜回去——这需要更大的信心，不是壮烈地跟随，而是安静地留守。', '撒下15，王上1', '主，撒督的忠心不是凭感情，而是凭辨别。帮助我在混乱中有撒督的清醒——看见神的手，站在神所立的那一边，安静忠心地守住岗位。阿们。', true),
    (240, '比拿雅', 'Benaiah', '王国时代', '其他', NULL, '正面', '勇敢执行命令是忠心的最高体现', '大卫的三十勇士之首，手无寸铁跳入坑中击杀狮子，单枪匹马击败埃及壮士，后成为所罗门的军队统帅，所罗门命他处决约押和示每时，他毫不退缩地忠心执行。', '他是那种你永远不需要怀疑他是否会执行命令的人。不是因为他没有判断力，而是因为他知道谁有权柄、谁值得信任。他的勇气不只是在战场上，也在政治最危险的时刻——奉命处死约押这样的大人物，他照样执行。', '撒下23，王上2', '主，比拿雅的勇气让我看到忠心的代价——不只是选择对的，还要有胆量去行对的。帮助我在需要勇气的地方不退缩，不找借口，忠心执行你所托付的事。阿们。', true),
    (236, '亚希多弗', 'Ahithophel', '王国时代', '其他', NULL, '警戒', '智慧若不以神为中心，终必自毁', '大卫最信任的谋士，被称为「如同询问神的话」，却在押沙龙叛乱时背叛大卫，计谋被胡示所败后自缢而死，是才智与忠诚一同崩溃的悲剧。', '他的谋略精准到圣经说「人去问他，如同询问神的话」。但他的智慧没有根植于神，而是根植于自己的地位和判断。当他的计谋被否决，他意识到失败已定，便回家安排后事、自缢而死——这是绝望的智慧，而非盼望的智慧。', '撒下15-17', '主，保护我不要成为亚希多弗——智慧卓绝却以自我为中心。帮助我的才能和判断始终向你的旨意俯伏，而不是凌驾于你之上。阿们。', true),
    (275, '友阿爹', 'Euodia', '新约时代', '其他', NULL, '警戒', '同工之间的不和会伤害教会的见证', '腓立比教会的女信徒，曾与保罗一同为福音劳苦，却与同工循都基发生争执，保罗在书信中点名请她们在主里和好，成为教会历史上最著名的同工冲突案例。', '保罗没有回避这个冲突，而是在公开书信中点名劝和。能被保罗点名「曾与我一同为福音劳苦」，说明她真实地服事过；但争执成了见证的绊脚石。同工的不和不是小事，它会让世界误解福音。', '腓4:2-3', '主，保护我与同工的关系，使我在基督里和好，让我们的一致成为福音的见证。阿们。', true),
    (276, '循都基', 'Syntyche', '新约时代', '其他', NULL, '警戒', '曾经的同工因争执需要在主里和好', '腓立比教会的女信徒，曾与保罗一同为福音劳苦，却与同工友阿爹发生争执，保罗在腓立比书中点名劝她们在主里和好，是新约中关于教会同工冲突的经典案例。', '她和友阿爹都是真实服事过的人，但争执让她们需要保罗公开调解。有时越是热心服事的人，越容易在同工关系上发生摩擦——因为都在乎，所以都有主见。保罗说「在主里」和好，提醒她们和好的基础不是谁对谁错，而是共同在主里的身份。', '腓4:2-3', '主，让我在与同工的冲突中先看自己的部分，以基督里共同的身份为基础和好。阿们。', true),
    (277, '乃缦的小女仆', 'Naaman''s Servant Girl', '王国时代', '其他', NULL, '正面', '一个被掳小女孩的一句话改变了一位大将军', '以色列被掳的小女孩，在叙利亚大将乃缦家中作女仆，得知主人患麻风，主动告诉主母有关以利沙先知能医治的消息，最终导致乃缦得医治、认识以色列的神，是圣经中以小见大的最感人案例之一。', '她是战争的受害者——被掳、为奴、异乡。她有充分的理由沉默，甚至袖手旁观。但她没有。她说：巴不得我主人去见撒马利亚的先知。一句话，从一个没有名字的女孩口中，启动了乃缦整个生命的转折。神有时用最小的人说出最重要的话。', '王下5:1-4', '主，乃缦的小女仆提醒我：你不需要我有地位、有名字，只需要我愿意开口。帮助我在日常的处境中，不让机会白白溜过。阿们。', true),
    (234, '尼布甲尼撒', 'Nebuchadnezzar', '被掳归回时代', '君王', '外邦君王', '混合', '骄傲之后的谦卑才是真正的认识神', '巴比伦王，亲眼见证但以理三友从火中被救、但以理解梦，自己却骄傲自大，被神击打如野兽七年，最终谦卑承认至高神的主权，是外邦君王中最戏剧性的悔改案例。', '七年之后，他抬起眼望天，理智回来了——他说：我称颂至高者，尊崇永活的神。这是外邦王口中说出的最真实的神学。骄傲到极致，神用七年旷野经历将他带回。没有任何人骄傲大到神无法对付。', '但1-4', '主，尼布甲尼撒用七年换来了真正认识你。帮助我不要等到被打到旷野才谦卑，今天就在你面前承认：一切荣耀都是你的。阿们。', true) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, name_en=EXCLUDED.name_en, era=EXCLUDED.era, role=EXCLUDED.role, kingdom=EXCLUDED.kingdom, character_type=EXCLUDED.character_type, lesson=EXCLUDED.lesson, summary=EXCLUDED.summary, witness=EXCLUDED.witness, scripture_ref=EXCLUDED.scripture_ref, prayer=EXCLUDED.prayer, is_active=EXCLUDED.is_active;

