    (238, '属灵历史不能保证属灵未来，每一个时刻都需要重新选择神', 1),
    (238, '你是否在某个领域靠「老本」过活，而非每天更新对神的委身？', 2),
    (239, '有时最大的忠心不是壮烈跟随，而是安静地坚守神给你的位置', 1),
    (239, '在混乱中辨别神所拣选的方向，并坚定站在那一边', 2),
    (240, '真正的勇敢不是没有恐惧，而是在恐惧中仍然行动', 1),
    (240, '忠心需要配合勇气——知道对的事还需要有胆量去做', 2),
    (240, '你在哪里需要比拿雅式的勇气：不只是知道，而是执行？', 3),
    (236, '你的智慧和才能是否以神为中心？还是以自我利益和判断为中心？', 1),
    (236, '亚希多弗的悲剧：当自己的判断成为最高标准，失败就意味着一切终结', 2),
    (236, '真正的智慧包含谦卑和悔改的空间，不是绝对的自我确信', 3),
    (275, '教会中你是否有需要和好的关系？今天迈出第一步', 1),
    (275, '同工之间的争执比外来的逼迫更伤害教会，不要让私人矛盾成为福音的拦阻', 2),
    (276, '和好的基础是「在主里」，不是谁让步谁赢了', 1),
    (276, '你现在有没有与某位同工的关系需要修复？', 2),
    (277, '你在你的处境中是否有「一句话」可以说出，引人归向神？', 1),
    (277, '即使你感到渺小、被忽视，神仍然可以使用你的一句话', 2),
    (234, '骄傲的顶峰离神的对付最近，检视你最自豪的领域', 1),
    (234, '尼布甲尼撒的七年旷野是否是你现在的处境？神在带你走向谦卑', 2),
    (234, '从高处被降卑不是终点，谦卑后的称颂才是神要的结局', 3);

