-- Insert themes
INSERT INTO character_themes (id, name, emoji, scripture, intro, summary, how_to_apply) VALUES
    ('faith-obedience', '信心与顺服', '🙏', '希伯来书11:1 信就是所望之事的实底，是未见之事的确据。', '信心不是盲目，而是在看不见结果时仍然顺服神的声音。亚伯拉罕的离乡、挪亚的方舟、路得的跟随——每一个信心的故事都始于一个看不见终点的「是」。', '真正的信心在疑惑中仍然选择顺服。', '{"今天辨别一件神在呼召你做但你还没行动的事", "把你的疑惑写下来交托给神", "找一位信心榜样分享你的挣扎"}'),
    ('repentance-restoration', '悔改与恢复', '🔄', '诗篇51:10 神啊，求你为我造清洁的心，使我里面重新有正直的灵。', '悔改是走向神的最短路径。大卫和彼得告诉我们，失败不是终点——即使是至极的罪，神的怜悯仍然比罪更大。', '悔改的目标不是感觉更好，而是关系的恢复和生命的更新。', '{"是否有一件事需要你真实地认罪悔改？", "悔改后接受神的饶恕，不再重复定罪自己", "找一位可信任的人分享你的悔改经历"}'),
    ('crisis-victory', '危机中的得胜', '⚔️', '历代志下20:17 这次你们不必争战，要摆好队伍，站着不动，看耶和华为你们施行拯救。', '危机是信仰最好的考场。约沙法、希西家和以斯帖在压力最大时转向神。', '危机不是神离开的信号，而是神要显出祂大能的时机。', '{"当前你面对的危机是什么？", "学习希西家，将问题铺在神面前", "在危机中先祷告，再行动"}'),
    ('workplace-faithfulness', '职场忠心', '💼', '歌罗西书3:23 无论做什么，都要从心里做，像是给主做的。', '约瑟、但以理和尼希米在复杂的职场中持守了信仰原则，成为神的见证。以斯帖「为此我来到王宫」，保罗在监狱中仍然写书信——环境不能拦阻委身的心。', '职场是信仰最真实的操练场，你的工作伦理就是你的信仰宣言。', '{"今天在工作中有没有机会见证基督的品格？", "在压力下坚持一个你不愿妥协的原则", "为你的职场同事祷告"}'),
    ('family-marriage', '家庭与婚姻', '👨‍👩‍👧', '路得记1:16 你往哪里去，我也往那里去。', '路得与波阿斯的忠贞、亚居拉与百基拉的同工、以撒与利百加的被引导——圣经中美好的婚姻都有神的参与和忠贞的品格作为基础。也有友阿爹与循都基警示我们：同工的不和会伤害团体。', '婚姻不只是两个人的幸福，更是神国的见证平台。', '{"在家庭中实践一个具体的爱的行动", "与配偶一起祷告和讨论共同的属灵目标", "反思家庭如何成为神国的工具"}'),
    ('prayer-power', '祷告的能力', '🕊️', '耶利米书33:3 你求告我，我就应允你。', '希西家的展开祷告、哈拿的哭泣祷告、但以理的恒常祷告、尼希米的箭祷——每一种祷告方式都是真实的，神都垂听。保罗为教会不断代祷，是代祷最美的示范。', '祷告的大小不在于词汇的优美，而在于心的真实。', '{"今天给神写一封诚实的信作为祷告", "设定一个每天固定的祷告时间", "为一个不可能的事情开始持续地祷告"}'),
    ('courage-boldness', '勇敢与胆量', '🦁', '约书亚记1:9 你当刚强壮胆，不要惧怕；因为耶和华你的神必与你同在。', '以斯帖的「我若死就死吧」、底波拉的率军出战、司提反被石头打时的祷告、施洗约翰指责希律——真正的勇气不是没有代价，而是知道代价仍然行动。', '真正的勇敢不是没有恐惧，而是在恐惧中仍然选择行动。', '{"有什么事你一直因恐惧而没有做？", "宣告约书亚记1:9，然后踏出一步", "找一位可以彼此鼓励勇气的朋友"}'),
    ('forgiveness-grace', '饶恕与恩典', '💞', '以弗所书4:32 彼此饶恕，正如神在基督里饶恕了你们一样。', '约瑟饶恕卖他的哥哥、大卫两次放过扫罗、保罗接纳曾半途而废的马可、腓利门饶恕逃奴阿尼西母、耶稣基督在十字架上说「父啊赦免他们」——每一个饶恕都是恩典的奇迹。', '饶恕是对自己的礼物，是打开神更大工作的门。', '{"有谁是你还没有饶恕的？", "饶恕不等于和好，先从心里释放开始", "为曾经伤害你的人祷告一周"}'),
    ('humble-leadership', '谦卑领导', '👑', '马太福音20:28 人子来，不是要受人的服侍，乃是要服侍人。', '摩西被称世上最谦和的人、大卫身为王仍称自己是仆人、巴拿巴甘心退到幕后、施洗约翰说「祂必兴旺我必衰微」、耶稣基督亲自俯身洗门徒的脚——谦卑是最稀缺也最有力的领导资质。', '领导力的大小不在于有多少人服侍你，而在于你服侍了多少人。', '{"今天主动做一件服侍他人的小事", "反思我的领导动机：是为影响力还是为服侍？", "找一个你可以帮助成长的人投资在他身上"}'),
    ('facing-temptation', '面对试探', '⚠️', '哥林多前书10:13 神是信实的，必不叫你们受试探过于所能受的。', '约瑟拒绝诱惑的「我怎能得罪神」、参孙被私欲败坏、大卫的闲暇之过、所罗门成功后的堕落、亚拿尼亚与撒非喇在教会中说谎——每一个故事都是镜子，照出我们的软弱处。', '识别自己的软弱处是智慧，在软弱处建立防线是成熟。', '{"诚实评估你最容易被试探的领域", "在那个领域建立一个具体的防护机制", "找一位可以互相问责的弟兄姊妹"}'),
    ('suffering-trust', '苦难中的信靠', '🌧️', '约伯记13:15 他必杀我；我虽无指望，然而我在他面前还要辩明我所行的道。', '约伯失去一切仍说「赏赐的是耶和华」、耶利米哭泣仍忠心传道、但以理被扔狮子坑、约瑟从坑到宰相、保罗在监狱中写出最喜乐的书信——苦难没有击垮他们，因为神比苦难更大。', '苦难中诚实地与神摔跤，比宗教式的接受更能经历神的真实。', '{"在苦难中不要假装没事，诚实与神对话", "阅读约伯记38-42章，听神如何回应", "寻找身边正在苦难中的人，陪伴而非给答案"}'),
    ('mission-service', '宣教与服事', '🌍', '使徒行传1:8 圣灵降临在你们身上，你们就必得着能力，作我的见证。', '保罗一生为福音劳苦、腓力向撒玛利亚人和埃提阿伯太监传福音、巴拿巴鼓励别人寻找同工、提摩太忠心传承、司提反边服事边见证——宣教是每一个信徒的呼召，从你所在的地方开始。', '宣教从日常生活的真实见证开始，不必等到特别的时机和场所。', '{"今天在你的日常关系中见证基督的一个品格", "为一个未信主的家人或朋友持续祷告", "问神：我在哪里是你的宣教士？"}'),
    ('small-faith-big-impact', '小人物大信心篇', '🌱', '马太福音17:20 你们若有信心像一粒芥菜种，就是对这座山说，你从这里挪到那里，它也必挪去。', '捐两个小钱的寡妇、献五饼二鱼的男孩、乃缦的小女仆、吕底亚、多加、安得烈——神国里最动人的故事往往来自被历史忽视的人。神使用小的，是因为祂要显出自己的大。', '神国里的大事，往往由小人物做成。你的微小不是限制，是神工作的入口。', '{"今天做一件看似微不足道的服事，相信神能放大它", "不因自己的小而等待，先把手中有的交给神", "思想：圣经中哪一个小人物的故事最激励你？为什么？"}'),
    ('repentance-hope', '悔改的盼望', '🔥', '约珥书2:13 你们要撕裂心肠，不要撕裂衣服，归向耶和华你们的神。', '悔改不是终点，而是新起点。从大卫的诗篇51篇、彼得在鸡叫后的痛哭、到十字架上最后时刻转向耶稣的强盗——圣经处处证明：没有任何人离神的怜悯太远，也没有任何时候太晚。', '悔改的门永远开着。真实的悔改不是感觉更好，而是转身面向神，让关系真正更新。', '{"今天在神面前做一次真实的认罪，不要用宗教话语装饰", "读诗篇51篇作为你自己的祷告", "有没有你一直没有回去的那个地方？今天回去。"}'),
    ('women-in-gods-kingdom', '女性在神国中的角色', '👑', '加拉太书3:28 并不分犹太人、希利尼人，自主的、为奴的，或男或女，因为你们在基督耶稣里都成为一了。', '从底波拉的领导、户勒大的先知权柄、抹大拉马利亚的复活见证、到路得的忠贞——圣经中的女性不是边缘人物，而是神国历史的关键参与者。她们每一个人都在那个时代突破了对女性的限制，完成了只有她们能完成的使命。', '神从来没有限制祂使用女性的方式和范围。在神国里，每一个女性都有她独特的、不可替代的呼召。', '{"研读一位圣经女性的生命，找到她与你处境的连接", "打破「我是女性所以不能」的内在限制，问神：你要我做什么？", "鼓励一位你认识的女性发挥她的属灵恩赐"}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, emoji=EXCLUDED.emoji, scripture=EXCLUDED.scripture, intro=EXCLUDED.intro, summary=EXCLUDED.summary, how_to_apply=EXCLUDED.how_to_apply;

